export const MATH_BANK_VERSION="TIM-MATH-20261111-V4-COMBINED";
export const REVISED_MATH_BANK={"MT01":[{"questionId":"MT01-Q01","prompt":"Calcule (−8) + 13.","expected":"5","alternatives":["−5","21","−21"],"explanation":"Les signes sont différents : 13 − 8 = 5, positif car 13 a la plus grande distance à zéro.","feedback":["Pour « −5 » : Tu as donné le signe du nombre −8 au lieu de celui de 13. Les signes sont différents : 13 − 8 = 5, positif car 13 a la plus grande distance à zéro.","Pour « 21 » : Additionner les distances à zéro ne convient pas pour deux signes différents. Les signes sont différents : 13 − 8 = 5, positif car 13 a la plus grande distance à zéro.","Pour « −21 » : Tu as additionné les distances et conservé un signe négatif. Les signes sont différents : 13 − 8 = 5, positif car 13 a la plus grande distance à zéro."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[1],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q02","prompt":"Calcule (−6) × 4.","expected":"−24","alternatives":["24","−10","10"],"explanation":"Un facteur négatif et un positif donnent un produit négatif ; 6 × 4 = 24, donc −24.","feedback":["Pour « 24 » : Il faut conserver un signe négatif avec des facteurs de signes différents. Un facteur négatif et un positif donnent un produit négatif ; 6 × 4 = 24, donc −24.","Pour « −10 » : −6 × 4 est une multiplication et non −6 − 4. Un facteur négatif et un positif donnent un produit négatif ; 6 × 4 = 24, donc −24.","Pour « 10 » : Il ne faut ni additionner ni supprimer le signe négatif. Un facteur négatif et un positif donnent un produit négatif ; 6 × 4 = 24, donc −24."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[2],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q03","prompt":"Calcule (−5) + (−7).","expected":"−12","alternatives":["12","−2","2"],"explanation":"Deux nombres négatifs s’additionnent en conservant le signe négatif : −(5 + 7) = −12.","feedback":["Pour « 12 » : On ne perd pas le signe moins lorsqu’on additionne deux négatifs. Deux nombres négatifs s’additionnent en conservant le signe négatif : −(5 + 7) = −12.","Pour « −2 » : Soustraire 7 et 5 ne correspond pas à cette addition. Deux nombres négatifs s’additionnent en conservant le signe négatif : −(5 + 7) = −12.","Pour « 2 » : Le résultat ne peut pas être positif si les deux termes sont négatifs. Deux nombres négatifs s’additionnent en conservant le signe négatif : −(5 + 7) = −12."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[1],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q04","prompt":"Calcule 4 − (−7).","expected":"11","alternatives":["−3","3","−11"],"explanation":"Soustraire −7 revient à ajouter +7 : 4 − (−7) = 4 + 7 = 11.","feedback":["Pour « −3 » : Il faut changer la soustraction de −7 en addition de +7. Soustraire −7 revient à ajouter +7 : 4 − (−7) = 4 + 7 = 11.","Pour « 3 » : Tu as soustrait 7 de 4, alors qu’on soustrait −7. Soustraire −7 revient à ajouter +7 : 4 − (−7) = 4 + 7 = 11.","Pour « −11 » : Le résultat de 4 + 7 est positif. Soustraire −7 revient à ajouter +7 : 4 − (−7) = 4 + 7 = 11."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[1],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q05","prompt":"Calcule (−3) − (+8).","expected":"−11","alternatives":["5","11","−5"],"explanation":"On part de −3 et on retire encore 8 : −3 − 8 = −11.","feedback":["Pour « 5 » : Ajouter 8 ne correspond pas à « retirer 8 ». On part de −3 et on retire encore 8 : −3 − 8 = −11.","Pour « 11 » : La valeur absolue 11 doit garder le signe négatif. On part de −3 et on retire encore 8 : −3 − 8 = −11.","Pour « −5 » : Tu as calculé une différence de distances au lieu de −3 − 8. On part de −3 et on retire encore 8 : −3 − 8 = −11."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[1],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q06","prompt":"Calcule (−8) ÷ (−2).","expected":"4","alternatives":["−4","16","−16"],"explanation":"Deux nombres négatifs donnent un quotient positif : 8 ÷ 2 = 4.","feedback":["Pour « −4 » : Le signe du quotient est positif puisque les deux nombres sont négatifs. Deux nombres négatifs donnent un quotient positif : 8 ÷ 2 = 4.","Pour « 16 » : Il s’agit d’une division, pas d’une multiplication. Deux nombres négatifs donnent un quotient positif : 8 ÷ 2 = 4.","Pour « −16 » : Tu as multiplié les valeurs en gardant un signe négatif. Deux nombres négatifs donnent un quotient positif : 8 ÷ 2 = 4."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[2],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q07","prompt":"Calcule (−2) × (−3) × (−4).","expected":"−24","alternatives":["24","−9","9"],"explanation":"Il y a trois facteurs négatifs : signe négatif. La valeur absolue vaut 2 × 3 × 4 = 24.","feedback":["Pour « 24 » : Trois facteurs négatifs produisent un résultat négatif. Il y a trois facteurs négatifs : signe négatif. La valeur absolue vaut 2 × 3 × 4 = 24.","Pour « −9 » : On doit multiplier les trois valeurs, pas les additionner. Il y a trois facteurs négatifs : signe négatif. La valeur absolue vaut 2 × 3 × 4 = 24.","Pour « 9 » : En plus du calcul de 2 × 3 × 4, il faut garder le signe négatif. Il y a trois facteurs négatifs : signe négatif. La valeur absolue vaut 2 × 3 × 4 = 24."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[2],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q08","prompt":"Calcule (+8,3) + (−6).","expected":"2,3","alternatives":["14,3","−2,3","8,9"],"explanation":"Les signes diffèrent : 8,3 − 6 = 2,3 ; le nombre positif a la plus grande valeur absolue.","feedback":["Pour « 14,3 » : Tu as additionné 8,3 et 6 au lieu de les soustraire. Les signes diffèrent : 8,3 − 6 = 2,3 ; le nombre positif a la plus grande valeur absolue.","Pour « −2,3 » : Le signe doit être positif puisque 8,3 est plus grand que 6. Les signes diffèrent : 8,3 − 6 = 2,3 ; le nombre positif a la plus grande valeur absolue.","Pour « 8,9 » : Tu as mal posé la différence décimale. Les signes diffèrent : 8,3 − 6 = 2,3 ; le nombre positif a la plus grande valeur absolue."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[1],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q09","prompt":"Quel est le résultat de (−4) × (−5) × (+8) × (−3) × (+9) × (+6) ?","expected":"−25 920","alternatives":["25 920","−4 320","−2 592"],"explanation":"Trois facteurs sont négatifs, donc le produit est négatif. 4 × 5 × 8 × 3 × 9 × 6 = 25 920.","feedback":["Pour « 25 920 » : Le nombre de facteurs négatifs est impair : le signe est négatif. Trois facteurs sont négatifs, donc le produit est négatif. 4 × 5 × 8 × 3 × 9 × 6 = 25 920.","Pour « −4 320 » : −4 320 oublie le dernier facteur 6. Trois facteurs sont négatifs, donc le produit est négatif. 4 × 5 × 8 × 3 × 9 × 6 = 25 920.","Pour « −2 592 » : Tu as perdu un facteur 10 en multipliant les valeurs absolues. Trois facteurs sont négatifs, donc le produit est négatif. 4 × 5 × 8 × 3 × 9 × 6 = 25 920."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[2],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"},{"questionId":"MT01-Q10","prompt":"Calcule (−3) × (4 − 7).","expected":"9","alternatives":["−9","−21","1"],"explanation":"On calcule d’abord 4 − 7 = −3, puis (−3) × (−3) = +9.","feedback":["Pour « −9 » : Le produit de deux nombres négatifs est positif. On calcule d’abord 4 − 7 = −3, puis (−3) × (−3) = +9.","Pour « −21 » : Tu as multiplié −3 par 7 sans calculer la parenthèse. On calcule d’abord 4 − 7 = −3, puis (−3) × (−3) = +9.","Pour « 1 » : Il faut calculer toute la parenthèse avant la multiplication. On calcule d’abord 4 − 7 = −3, puis (−3) × (−3) = +9."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[2],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS01"}],"MT02":[{"questionId":"MT02-Q01","prompt":"Calcule 3/4 + 1/8.","expected":"7/8","alternatives":["4/12","1/2","7/12"],"explanation":"3/4 = 6/8 ; 6/8 + 1/8 = 7/8.","feedback":["Pour « 4/12 » : Il ne faut jamais additionner directement les dénominateurs. 3/4 = 6/8 ; 6/8 + 1/8 = 7/8.","Pour « 1/2 » : Tu as oublié une partie de 3/4 : cela vaut 6/8. 3/4 = 6/8 ; 6/8 + 1/8 = 7/8.","Pour « 7/12 » : Le dénominateur commun correct est 8, pas 12. 3/4 = 6/8 ; 6/8 + 1/8 = 7/8."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[3],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q02","prompt":"Calcule les 2/5 de 30.","expected":"12","alternatives":["6","15","60"],"explanation":"Un cinquième de 30 vaut 6 ; deux cinquièmes valent 2 × 6 = 12.","feedback":["Pour « 6 » : 6 ne représente qu’un cinquième : il en faut deux. Un cinquième de 30 vaut 6 ; deux cinquièmes valent 2 × 6 = 12.","Pour « 15 » : 15 représente la moitié de 30, et non ses deux cinquièmes. Un cinquième de 30 vaut 6 ; deux cinquièmes valent 2 × 6 = 12.","Pour « 60 » : Multiplier par 2 sans diviser par 5 n’applique pas la fraction. Un cinquième de 30 vaut 6 ; deux cinquièmes valent 2 × 6 = 12."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[4],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q03","prompt":"Calcule 4/5 − 11/15.","expected":"1/15","alternatives":["−7/10","−7/15","15/75"],"explanation":"4/5 = 12/15 ; puis 12/15 − 11/15 = 1/15.","feedback":["Pour « −7/10 » : Les dénominateurs doivent être rendus identiques avant de soustraire. 4/5 = 12/15 ; puis 12/15 − 11/15 = 1/15.","Pour « −7/15 » : Tu as soustrait 11 à 4 sans convertir 4/5 en quinzièmes. 4/5 = 12/15 ; puis 12/15 − 11/15 = 1/15.","Pour « 15/75 » : 15/75 n’est pas la différence obtenue après conversion. 4/5 = 12/15 ; puis 12/15 − 11/15 = 1/15."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[3],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q04","prompt":"Calcule 3/8 + 5/6.","expected":"29/24","alternatives":["8/14","8/24","23/24"],"explanation":"3/8 = 9/24 et 5/6 = 20/24 : on obtient 29/24.","feedback":["Pour « 8/14 » : Additionner les numérateurs et les dénominateurs est interdit. 3/8 = 9/24 et 5/6 = 20/24 : on obtient 29/24.","Pour « 8/24 » : Tu as conservé les numérateurs 3 et 5 au lieu de les convertir. 3/8 = 9/24 et 5/6 = 20/24 : on obtient 29/24.","Pour « 23/24 » : Les numérateurs convertis donnent 9 + 20 = 29, pas 23. 3/8 = 9/24 et 5/6 = 20/24 : on obtient 29/24."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[3],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q05","prompt":"Calcule 4/9 − 7/12.","expected":"−5/36","alternatives":["5/36","−3/36","−3/21"],"explanation":"Avec le dénominateur 36 : 4/9 = 16/36 et 7/12 = 21/36. Donc 16/36 − 21/36 = −5/36.","feedback":["Pour « 5/36 » : La deuxième fraction est plus grande : la différence doit être négative. Avec le dénominateur 36 : 4/9 = 16/36 et 7/12 = 21/36. Donc 16/36 − 21/36 = −5/36.","Pour « −3/36 » : 16 − 21 = −5, pas −3. Avec le dénominateur 36 : 4/9 = 16/36 et 7/12 = 21/36. Donc 16/36 − 21/36 = −5/36.","Pour « −3/21 » : On ne soustrait pas directement les dénominateurs 9 et 12. Avec le dénominateur 36 : 4/9 = 16/36 et 7/12 = 21/36. Donc 16/36 − 21/36 = −5/36."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[3],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q06","prompt":"Calcule (15/16) × (7/10) × (12/7).","expected":"9/8","alternatives":["9/16","45/16","63/80"],"explanation":"On simplifie les 7, puis 15/10 = 3/2 et 12/16 = 3/4 : (3 × 3)/(2 × 4) = 9/8.","feedback":["Pour « 9/16 » : Tu as oublié de simplifier ou de multiplier un facteur. On simplifie les 7, puis 15/10 = 3/2 et 12/16 = 3/4 : (3 × 3)/(2 × 4) = 9/8.","Pour « 45/16 » : 45/16 ne correspond pas au produit des trois fractions. On simplifie les 7, puis 15/10 = 3/2 et 12/16 = 3/4 : (3 × 3)/(2 × 4) = 9/8.","Pour « 63/80 » : 63/80 oublie une partie de la simplification des facteurs. On simplifie les 7, puis 15/10 = 3/2 et 12/16 = 3/4 : (3 × 3)/(2 × 4) = 9/8."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[4],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q07","prompt":"Donne sous forme irréductible le résultat de (−2/3) × (3/5).","expected":"−2/5","alternatives":["2/5","−6/15","−5/6"],"explanation":"Le produit est négatif et vaut (−2 × 3)/(3 × 5) = −6/15 = −2/5, sous forme simplifiée.","feedback":["Pour « 2/5 » : Un seul facteur est négatif : le produit est négatif. Le produit est négatif et vaut (−2 × 3)/(3 × 5) = −6/15 = −2/5, sous forme simplifiée.","Pour « −6/15 » : −6/15 a la même valeur, mais cette écriture n’est pas irréductible comme le demande la consigne. Le produit est négatif et vaut (−2 × 3)/(3 × 5) = −6/15 = −2/5, sous forme simplifiée.","Pour « −5/6 » : Diviser les numérateurs et les dénominateurs entre eux ne donne pas le produit. Le produit est négatif et vaut (−2 × 3)/(3 × 5) = −6/15 = −2/5, sous forme simplifiée."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[4],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q08","prompt":"Calcule 3/7 ÷ 4/5.","expected":"15/28","alternatives":["12/35","20/21","7/12"],"explanation":"On multiplie par l’inverse de la deuxième fraction : 3/7 × 5/4 = 15/28.","feedback":["Pour « 12/35 » : Tu as multiplié par 4/5 sans l’inverser. On multiplie par l’inverse de la deuxième fraction : 3/7 × 5/4 = 15/28.","Pour « 20/21 » : Ce quotient ne vient pas du produit 3 × 5 sur 7 × 4. On multiplie par l’inverse de la deuxième fraction : 3/7 × 5/4 = 15/28.","Pour « 7/12 » : Tu as inversé la mauvaise fraction ou inversé le résultat. On multiplie par l’inverse de la deuxième fraction : 3/7 × 5/4 = 15/28."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[4],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q09","prompt":"Simplifie 84/126 en fraction irréductible.","expected":"2/3","alternatives":["4/6","3/2","7/9"],"explanation":"Le plus grand diviseur commun de 84 et 126 est 42 : 84 ÷ 42 = 2 et 126 ÷ 42 = 3.","feedback":["Pour « 4/6 » : 4/6 a la même valeur, mais n’est pas irréductible. Le plus grand diviseur commun de 84 et 126 est 42 : 84 ÷ 42 = 2 et 126 ÷ 42 = 3.","Pour « 3/2 » : 3/2 est l’inverse de 2/3. Le plus grand diviseur commun de 84 et 126 est 42 : 84 ÷ 42 = 2 et 126 ÷ 42 = 3.","Pour « 7/9 » : La fraction 7/9 n’a pas la même valeur que 84/126. Le plus grand diviseur commun de 84 et 126 est 42 : 84 ÷ 42 = 2 et 126 ÷ 42 = 3."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[4],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"},{"questionId":"MT02-Q10","prompt":"Un réservoir contient 75 L. On utilise les 2/3 de son contenu. Combien de litres sont utilisés ?","expected":"50 L","alternatives":["25 L","112,5 L","150 L"],"explanation":"Un tiers de 75 vaut 25 L ; deux tiers valent 2 × 25 = 50 L.","feedback":["Pour « 25 L » : 25 L ne correspond qu’à un tiers du réservoir. Un tiers de 75 vaut 25 L ; deux tiers valent 2 × 25 = 50 L.","Pour « 112,5 L » : 112,5 L dépasse le contenu du réservoir alors qu’on en utilise moins que la totalité. Un tiers de 75 vaut 25 L ; deux tiers valent 2 × 25 = 50 L.","Pour « 150 L » : Tu as multiplié par 2 sans diviser par 3. Un tiers de 75 vaut 25 L ; deux tiers valent 2 × 25 = 50 L."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[4],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS02"}],"MT03":[{"questionId":"MT03-Q01","prompt":"Effectue ce calcul : Calcule (−3)³.","expected":"−27","alternatives":["27","−9","9"],"explanation":"Trois facteurs −3 donnent (−3) × (−3) × (−3) = −27.","feedback":["Pour « 27 » : Un nombre impair de facteurs négatifs donne un produit négatif. Trois facteurs −3 donnent (−3) × (−3) × (−3) = −27.","Pour « −9 » : L’exposant indique le nombre de facteurs, pas « multiplier par 3 ». Trois facteurs −3 donnent (−3) × (−3) × (−3) = −27.","Pour « 9 » : Tu as perdu le signe moins et confondu puissance et multiplication par l’exposant. Trois facteurs −3 donnent (−3) × (−3) × (−3) = −27."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q02","prompt":"Effectue ce calcul : Calcule 2⁻³.","expected":"1/8","alternatives":["−8","8","1/6"],"explanation":"Un exposant négatif demande l’inverse : 2⁻³ = 1/(2³) = 1/8.","feedback":["Pour « −8 » : Le signe moins de l’exposant n’est pas celui du résultat. Un exposant négatif demande l’inverse : 2⁻³ = 1/(2³) = 1/8.","Pour « 8 » : Tu as oublié de prendre l’inverse de 8. Un exposant négatif demande l’inverse : 2⁻³ = 1/(2³) = 1/8.","Pour « 1/6 » : 2³ vaut 8, pas 6. Un exposant négatif demande l’inverse : 2⁻³ = 1/(2³) = 1/8."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q03","prompt":"Effectue ce calcul : Calcule 3⁴.","expected":"81","alternatives":["12","64","27"],"explanation":"3⁴ signifie 3 × 3 × 3 × 3 = 81.","feedback":["Pour « 12 » : Tu as fait 3 × 4, mais il faut quatre facteurs égaux à 3. 3⁴ signifie 3 × 3 × 3 × 3 = 81.","Pour « 64 » : 64 correspond à 4³, et non 3⁴. 3⁴ signifie 3 × 3 × 3 × 3 = 81.","Pour « 27 » : 27 ne compte que trois facteurs de 3. 3⁴ signifie 3 × 3 × 3 × 3 = 81."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q04","prompt":"Effectue ce calcul : Calcule (−2)⁶.","expected":"64","alternatives":["−64","−12","12"],"explanation":"Avec six facteurs −2, le nombre de signes négatifs est pair : (−2)⁶ = +64.","feedback":["Pour « −64 » : Une puissance paire d’une base négative est positive. Avec six facteurs −2, le nombre de signes négatifs est pair : (−2)⁶ = +64.","Pour « −12 » : Tu as multiplié −2 par 6 au lieu de calculer la puissance. Avec six facteurs −2, le nombre de signes négatifs est pair : (−2)⁶ = +64.","Pour « 12 » : L’exposant 6 n’est pas un multiplicateur ordinaire. Avec six facteurs −2, le nombre de signes négatifs est pair : (−2)⁶ = +64."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q05","prompt":"Calcule −2⁶ (sans parenthèses autour de −2).","expected":"−64","alternatives":["64","−12","12"],"explanation":"Sans parenthèses, la puissance s’applique à 2 seulement : −(2⁶) = −64.","feedback":["Pour « 64 » : 64 serait le résultat de (−2)⁶, où le signe moins est dans les parenthèses. Sans parenthèses, la puissance s’applique à 2 seulement : −(2⁶) = −64.","Pour « −12 » : Tu as fait −2 × 6, pas −(2⁶). Sans parenthèses, la puissance s’applique à 2 seulement : −(2⁶) = −64.","Pour « 12 » : Le résultat ne peut pas être +12 : il faut calculer 2⁶ avant le signe moins. Sans parenthèses, la puissance s’applique à 2 seulement : −(2⁶) = −64."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q06","prompt":"Effectue ce calcul : Calcule 5⁰.","expected":"1","alternatives":["0","5","25"],"explanation":"Tout nombre non nul élevé à la puissance zéro vaut 1 : 5⁰ = 1.","feedback":["Pour « 0 » : L’exposant zéro ne signifie pas que le résultat est zéro. Tout nombre non nul élevé à la puissance zéro vaut 1 : 5⁰ = 1.","Pour « 5 » : 5¹ vaut 5, mais 5⁰ vaut 1. Tout nombre non nul élevé à la puissance zéro vaut 1 : 5⁰ = 1.","Pour « 25 » : 25 correspond à 5², pas 5⁰. Tout nombre non nul élevé à la puissance zéro vaut 1 : 5⁰ = 1."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q07","prompt":"Effectue ce calcul : Calcule 4⁻².","expected":"1/16","alternatives":["−16","16","1/8"],"explanation":"4⁻² = 1/4² = 1/16. Revois les propriétés expliquées dans la leçon.","feedback":["Pour « −16 » : Un exposant négatif n’implique pas un résultat négatif. 4⁻² = 1/4² = 1/16.","Pour « 16 » : Tu as calculé le carré sans prendre l’inverse. 4⁻² = 1/4² = 1/16.","Pour « 1/8 » : L’inverse demandé est celui du carré 16, et non du double 8. 4⁻² = 1/4² = 1/16."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q08","prompt":"Effectue ce calcul : Calcule (−2)⁵.","expected":"−32","alternatives":["32","−10","10"],"explanation":"Il y a cinq facteurs négatifs, donc le résultat est négatif : (−2)⁵ = −32.","feedback":["Pour « 32 » : Le résultat doit être négatif pour une puissance impaire de −2. Il y a cinq facteurs négatifs, donc le résultat est négatif : (−2)⁵ = −32.","Pour « −10 » : Tu as fait −2 × 5 au lieu de calculer la puissance. Il y a cinq facteurs négatifs, donc le résultat est négatif : (−2)⁵ = −32.","Pour « 10 » : Tu as confondu produit par 5 et puissance cinquième. Il y a cinq facteurs négatifs, donc le résultat est négatif : (−2)⁵ = −32."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q09","prompt":"Calcule 2³ × 2⁴.","expected":"128","alternatives":["64","256","24"],"explanation":"Les exposants s’additionnent lorsqu’on multiplie deux puissances de même base : 2³ × 2⁴ = 2⁷ = 128.","feedback":["Pour « 64 » : 2⁶ = 64 : tu as oublié un exposant. Les exposants s’additionnent lorsqu’on multiplie deux puissances de même base : 2³ × 2⁴ = 2⁷ = 128.","Pour « 256 » : 2⁸ = 256 : tu as compté huit facteurs de 2 au lieu de sept. Les exposants s’additionnent lorsqu’on multiplie deux puissances de même base : 2³ × 2⁴ = 2⁷ = 128.","Pour « 24 » : 24 n’est pas le résultat d’un produit de puissances. Les exposants s’additionnent lorsqu’on multiplie deux puissances de même base : 2³ × 2⁴ = 2⁷ = 128."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"},{"questionId":"MT03-Q10","prompt":"Calcule 2⁵ ÷ 2².","expected":"8","alternatives":["4","32","128"],"explanation":"Pour des puissances de même base, les exposants se soustraient : 2⁵ ÷ 2² = 2³ = 8.","feedback":["Pour « 4 » : 2² = 4, mais il faut soustraire 5 − 2 = 3. Pour des puissances de même base, les exposants se soustraient : 2⁵ ÷ 2² = 2³ = 8.","Pour « 32 » : 32 correspond au numérateur sans division. Pour des puissances de même base, les exposants se soustraient : 2⁵ ÷ 2² = 2³ = 8.","Pour « 128 » : Tu as ajouté les exposants au lieu de les soustraire. Pour des puissances de même base, les exposants se soustraient : 2⁵ ÷ 2² = 2³ = 8."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS03"}],"MT04":[{"questionId":"MT04-Q01","prompt":"Écris 63 000 en écriture scientifique.","expected":"6,3 × 10⁴","alternatives":["63 × 10³","6,3 × 10³","0,63 × 10⁴"],"explanation":"63 000 = 6,3 × 10⁴ : le coefficient est au moins 1 et strictement inférieur à 10.","feedback":["Pour « 63 × 10³ » : 63 × 10³ a la même valeur, mais son coefficient 63 n’est pas normalisé. 63 000 = 6,3 × 10⁴ : le coefficient est au moins 1 et strictement inférieur à 10.","Pour « 6,3 × 10³ » : 6,3 × 10³ ne donne que 6 300. 63 000 = 6,3 × 10⁴ : le coefficient est au moins 1 et strictement inférieur à 10.","Pour « 0,63 × 10⁴ » : 0,63 × 10⁴ ne vaut que 6 300 et son coefficient est trop petit. 63 000 = 6,3 × 10⁴ : le coefficient est au moins 1 et strictement inférieur à 10."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q02","prompt":"Écris 0,009 en écriture scientifique.","expected":"9 × 10⁻³","alternatives":["0,9 × 10⁻²","9 × 10³","9 × 10⁻²"],"explanation":"0,009 = 9 millièmes = 9 × 10⁻³.","feedback":["Pour « 0,9 × 10⁻² » : 0,9 × 10⁻² a la même valeur, mais son coefficient 0,9 est inférieur à 1. 0,009 = 9 millièmes = 9 × 10⁻³.","Pour « 9 × 10³ » : 9 × 10³ vaut 9 000. 0,009 = 9 millièmes = 9 × 10⁻³.","Pour « 9 × 10⁻² » : 9 × 10⁻² vaut 0,09, dix fois trop grand. 0,009 = 9 millièmes = 9 × 10⁻³."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q03","prompt":"Écris 0,00072 en écriture scientifique.","expected":"7,2 × 10⁻⁴","alternatives":["7,2 × 10⁻³","72 × 10⁻⁵","7,2 × 10⁴"],"explanation":"On décale la virgule de quatre rangs vers la droite pour obtenir 7,2 : 0,00072 = 7,2 × 10⁻⁴.","feedback":["Pour « 7,2 × 10⁻³ » : 7,2 × 10⁻³ vaut 0,0072, dix fois trop grand. On décale la virgule de quatre rangs vers la droite pour obtenir 7,2 : 0,00072 = 7,2 × 10⁻⁴.","Pour « 72 × 10⁻⁵ » : 72 × 10⁻⁵ a la même valeur, mais 72 n’est pas un coefficient scientifique valide. On décale la virgule de quatre rangs vers la droite pour obtenir 7,2 : 0,00072 = 7,2 × 10⁻⁴.","Pour « 7,2 × 10⁴ » : L’exposant positif ferait un nombre beaucoup trop grand. On décale la virgule de quatre rangs vers la droite pour obtenir 7,2 : 0,00072 = 7,2 × 10⁻⁴."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q04","prompt":"Écris 4 520 en écriture scientifique.","expected":"4,52 × 10³","alternatives":["45,2 × 10²","4,52 × 10²","4,52 × 10⁻³"],"explanation":"On place la virgule après le premier chiffre non nul : 4 520 = 4,52 × 10³.","feedback":["Pour « 45,2 × 10² » : La valeur est égale, mais le coefficient 45,2 est trop grand pour une écriture scientifique. On place la virgule après le premier chiffre non nul : 4 520 = 4,52 × 10³.","Pour « 4,52 × 10² » : 4,52 × 10² vaut 452, pas 4 520. On place la virgule après le premier chiffre non nul : 4 520 = 4,52 × 10³.","Pour « 4,52 × 10⁻³ » : Un exposant négatif représenterait un tout petit nombre. On place la virgule après le premier chiffre non nul : 4 520 = 4,52 × 10³."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q05","prompt":"Calcule 10³ × 10⁻⁵.","expected":"10⁻²","alternatives":["10⁸","10²","10⁻¹⁵"],"explanation":"Même base : on additionne les exposants 3 + (−5) = −2. Donc 10³ × 10⁻⁵ = 10⁻².","feedback":["Pour « 10⁸ » : Tu as soustrait le nombre négatif au lieu d’additionner les exposants. Même base : on additionne les exposants 3 + (−5) = −2. Donc 10³ × 10⁻⁵ = 10⁻².","Pour « 10² » : Tu as perdu le signe négatif du résultat −2. Même base : on additionne les exposants 3 + (−5) = −2. Donc 10³ × 10⁻⁵ = 10⁻².","Pour « 10⁻¹⁵ » : On n’effectue pas le produit 3 × (−5) des exposants. Même base : on additionne les exposants 3 + (−5) = −2. Donc 10³ × 10⁻⁵ = 10⁻²."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q06","prompt":"Calcule 10⁷ ÷ 10³.","expected":"10⁴","alternatives":["10¹⁰","10³","10²¹"],"explanation":"Même base : on soustrait les exposants, 7 − 3 = 4. Le quotient vaut 10⁴.","feedback":["Pour « 10¹⁰ » : Tu as additionné les exposants au lieu de les soustraire. Même base : on soustrait les exposants, 7 − 3 = 4. Le quotient vaut 10⁴.","Pour « 10³ » : Tu as gardé l’exposant du diviseur au lieu de faire 7 − 3. Même base : on soustrait les exposants, 7 − 3 = 4. Le quotient vaut 10⁴.","Pour « 10²¹ » : Tu as multiplié les exposants, ce qui ne convient pas à la division. Même base : on soustrait les exposants, 7 − 3 = 4. Le quotient vaut 10⁴."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q07","prompt":"Calcule (10⁻²)³.","expected":"10⁻⁶","alternatives":["10⁻⁵","10⁶","10⁻⁸"],"explanation":"On multiplie les exposants : (10⁻²)³ = 10^(−2 × 3) = 10⁻⁶.","feedback":["Pour « 10⁻⁵ » : Additionner −2 et 3 ne donne pas l’exposant d’une puissance de puissance. On multiplie les exposants : (10⁻²)³ = 10^(−2 × 3) = 10⁻⁶.","Pour « 10⁶ » : Tu as oublié le signe négatif de l’exposant −2. On multiplie les exposants : (10⁻²)³ = 10^(−2 × 3) = 10⁻⁶.","Pour « 10⁻⁸ » : Tu as remplacé la multiplication −2 × 3 par une autre opération. On multiplie les exposants : (10⁻²)³ = 10^(−2 × 3) = 10⁻⁶."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q08","prompt":"Une distance de 4,5 km correspond à combien de mètres ?","expected":"4 500 m","alternatives":["450 m","45 000 m","0,0045 m"],"explanation":"1 km = 1 000 m, donc 4,5 × 1 000 = 4 500 m.","feedback":["Pour « 450 m » : Tu as multiplié par 100 au lieu de 1 000. 1 km = 1 000 m, donc 4,5 × 1 000 = 4 500 m.","Pour « 45 000 m » : Tu as multiplié par 10 000 au lieu de 1 000. 1 km = 1 000 m, donc 4,5 × 1 000 = 4 500 m.","Pour « 0,0045 m » : Tu as divisé par 1 000 alors qu’il faut multiplier. 1 km = 1 000 m, donc 4,5 × 1 000 = 4 500 m."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q09","prompt":"Une masse de 2,5 mg correspond à combien de grammes ?","expected":"0,0025 g","alternatives":["0,025 g","2 500 g","0,00025 g"],"explanation":"« Milli » signifie un millième : 2,5 mg = 2,5 ÷ 1 000 g = 0,0025 g.","feedback":["Pour « 0,025 g » : Tu n’as divisé que par 100, donc dix fois trop grand. « Milli » signifie un millième : 2,5 mg = 2,5 ÷ 1 000 g = 0,0025 g.","Pour « 2 500 g » : Tu as multiplié par 1 000 au lieu de diviser. « Milli » signifie un millième : 2,5 mg = 2,5 ÷ 1 000 g = 0,0025 g.","Pour « 0,00025 g » : Tu as divisé par 10 000 au lieu de 1 000. « Milli » signifie un millième : 2,5 mg = 2,5 ÷ 1 000 g = 0,0025 g."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"},{"questionId":"MT04-Q10","prompt":"Écris 5,4 × 10⁻³ sous forme décimale.","expected":"0,0054","alternatives":["0,054","5 400","0,00054"],"explanation":"Multiplier par 10⁻³ revient à diviser par 1 000 : 5,4 ÷ 1 000 = 0,0054.","feedback":["Pour « 0,054 » : Tu n’as déplacé la virgule que de deux rangs au lieu de trois. Multiplier par 10⁻³ revient à diviser par 1 000 : 5,4 ÷ 1 000 = 0,0054.","Pour « 5 400 » : Tu as appliqué une puissance positive, pas 10⁻³. Multiplier par 10⁻³ revient à diviser par 1 000 : 5,4 ÷ 1 000 = 0,0054.","Pour « 0,00054 » : Tu as déplacé la virgule de quatre rangs au lieu de trois. Multiplier par 10⁻³ revient à diviser par 1 000 : 5,4 ÷ 1 000 = 0,0054."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS04"}],"MT05":[{"questionId":"MT05-Q01","prompt":"Le triangle ABC est rectangle en B. Quel côté est son hypoténuse ?","expected":"[AC]","alternatives":["[AB]","[BC]","[ABC]"],"explanation":"L'angle droit est en B ; le côté opposé est [AC].","feedback":["[AB] rejoint B : il forme l’angle droit, ce n’est pas le côté opposé.","[BC] rejoint B : il forme lui aussi l’angle droit.","[ABC] n’est pas un segment : trois lettres désignent le triangle ou l’angle, pas un côté."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q02","prompt":"Dans le triangle RST rectangle en T, quel segment est le plus long ?","expected":"[RS]","alternatives":["[RT]","[ST]","On ne peut pas le savoir"],"explanation":"Le plus long côté d'un triangle rectangle est l'hypoténuse, opposée à l'angle droit T : [RS].","feedback":["[RT] touche l’angle droit en T ; il ne peut pas être l’hypoténuse.","[ST] touche également l’angle droit en T.","Le fait que le triangle soit rectangle en T suffit à trouver son côté le plus long."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q03","prompt":"Le triangle MNP est rectangle en M. Quels côtés forment l'angle droit ?","expected":"[MN] et [MP]","alternatives":["[MN] et [NP]","[MP] et [NP]","[NP] et [NP]"],"explanation":"Les deux côtés qui se rejoignent au sommet M sont [MN] et [MP].","feedback":["[NP] est en face du sommet M : c’est l’hypoténuse.","[NP] ne touche pas M : il ne forme pas l’angle droit.","On a besoin de deux côtés distincts qui se rencontrent en M."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q04","prompt":"Dans le triangle DEF, les droites (DE) et (EF) sont perpendiculaires. À quel sommet se trouve l'angle droit ?","expected":"E","alternatives":["D","F","On ne peut pas le savoir"],"explanation":"Les côtés [ED] et [EF] se rencontrent en E et sont perpendiculaires ; l'angle DEF vaut 90°.","feedback":["Le point D est sur une seule des deux droites citées ; leur sommet commun est E.","Le point F est sur une seule des deux droites citées ; leur sommet commun est E.","Des segments perpendiculaires qui se rejoignent en E définissent un angle droit en E."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q05","prompt":"ABC est rectangle en A. Quelle égalité de Pythagore faut-il écrire ?","expected":"BC² = AB² + AC²","alternatives":["AB² = AC² + BC²","AC² = AB² + BC²","BC = AB + AC"],"explanation":"[BC] est opposé à A : BC² = AB² + AC².","feedback":["[AB] touche A et ne peut pas être l’hypoténuse.","[AC] touche également A et ne peut pas être l’hypoténuse.","Pythagore relie les carrés des longueurs, et non les longueurs directement."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q06","prompt":"Dans un triangle rectangle en C, lequel de ces côtés se trouve en face de l'angle droit ?","expected":"[AB]","alternatives":["[AC]","[BC]","Aucun des trois"],"explanation":"Le côté opposé à C est [AB], donc l'hypoténuse.","feedback":["[AC] touche le sommet C : c’est un côté de l’angle droit.","[BC] touche le sommet C : c’est l’autre côté de l’angle droit.","Tout triangle rectangle possède une hypoténuse."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q07","prompt":"On connaît seulement deux longueurs d'un triangle ; aucun angle droit n'est donné. Peut-on appliquer directement le théorème de Pythagore ?","expected":"Non : il faut savoir que le triangle est rectangle.","alternatives":["Oui : deux longueurs suffisent.","Oui : tous les triangles vérifient Pythagore.","Oui : si la figure ressemble à un triangle rectangle."],"explanation":"Le théorème de Pythagore direct nécessite un triangle rectangle établi dans l'énoncé ou démontré.","feedback":["Deux longueurs ne prouvent pas qu’un triangle possède un angle droit.","L’égalité de Pythagore n’est pas vraie dans tous les triangles.","L’apparence d’un dessin ne constitue pas une démonstration."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q08","prompt":"L'angle KLM mesure 90°. À quel sommet se trouve l'angle droit ?","expected":"L","alternatives":["K","M","Au milieu du segment [KM]"],"explanation":"Dans l'écriture d'un angle à trois lettres, le sommet est la lettre du milieu : L.","feedback":["K est une extrémité du premier rayon, pas le sommet de l’angle KLM.","M est une extrémité du second rayon, pas le sommet.","Une mesure d’angle est située à un sommet du triangle, ici L."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q09","prompt":"Le triangle UVW est rectangle en V. Dans l'égalité UW² = UV² + VW², que représente [UW] ?","expected":"L’hypoténuse","alternatives":["Un côté de l’angle droit","La hauteur issue de V","Une médiane"],"explanation":"[UW] est opposé au sommet V où se trouve l'angle droit : c'est l'hypoténuse.","feedback":["Les côtés de l’angle droit sont [UV] et [VW].","Rien n’indique ici une hauteur ; [UW] est le côté opposé à l’angle droit.","Une médiane relie un sommet au milieu du côté opposé ; ce n’est pas la donnée utilisée."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"},{"questionId":"MT05-Q10","prompt":"Le triangle XYZ est rectangle en Z. Quels segments ont Z comme extrémité et encadrent l'angle droit ?","expected":"[XZ] et [YZ]","alternatives":["[XY] et [XZ]","[XY] et [YZ]","[XY] uniquement"],"explanation":"Les côtés adjacents à l'angle droit en Z sont [XZ] et [YZ].","feedback":["[XY] est opposé à Z : ce segment est l’hypoténuse.","[XY] est le côté situé en face de l’angle droit.","Deux côtés se rencontrent en Z, pas seulement un."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS05"}],"MT06":[{"questionId":"MT06-Q01","prompt":"ABC est rectangle en A ; AB = 9 cm et AC = 12 cm. Quelle est la longueur BC ?","expected":"15 cm","alternatives":["21 cm","3 cm","√63 cm"],"explanation":"BC² = 9² + 12² = 81 + 144 = 225 ; BC = 15 cm.","feedback":["21 résulte de 9 + 12, mais il faut additionner les carrés.","3 provient de 12 − 9, pas du calcul de l’hypoténuse.","√63 correspond à une différence, alors que BC est l’hypoténuse."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q02","prompt":"RST est rectangle en T ; RS = 13 cm et RT = 12 cm. Combien mesure TS ?","expected":"5 cm","alternatives":["1 cm","√313 cm","25 cm"],"explanation":"TS² = RS² − RT² = 169 − 144 = 25 ; TS = 5 cm.","feedback":["13 − 12 donne 1, mais Pythagore utilise les carrés.","√313 ajoute les carrés ; lorsque l’hypoténuse est connue, il faut soustraire.","25 est le carré de la longueur cherchée, pas la longueur en centimètres."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q03","prompt":"MNP est rectangle en M ; MN = 6 cm et MP = 8 cm. Combien mesure NP ?","expected":"10 cm","alternatives":["14 cm","2 cm","√28 cm"],"explanation":"NP² = 6² + 8² = 100, donc NP = 10 cm.","feedback":["6 + 8 = 14 n’est pas l’application du théorème.","8 − 6 = 2 ne calcule pas l’hypoténuse.","√28 correspond à 8² − 6², alors qu’on cherche le grand côté."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q04","prompt":"GHI est rectangle en G ; HI = 10 cm et GH = 8 cm. Quelle est la longueur GI ?","expected":"6 cm","alternatives":["18 cm","2 cm","√164 cm"],"explanation":"GI² = HI² − GH² = 100 − 64 = 36 ; GI = 6 cm.","feedback":["Additionner directement 10 et 8 ne donne pas le troisième côté.","10 − 8 est une soustraction des longueurs, pas des carrés.","√164 résulte de l’addition 10² + 8² au lieu de la soustraction."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q05","prompt":"Une échelle touche un mur à 2,4 m de hauteur ; son pied est à 0,7 m du mur. Le mur est perpendiculaire au sol. Quelle est la longueur de l'échelle ?","expected":"2,5 m","alternatives":["3,1 m","1,7 m","√5,27 m"],"explanation":"L² = 2,4² + 0,7² = 5,76 + 0,49 = 6,25 ; L = 2,5 m.","feedback":["2,4 + 0,7 = 3,1 : additionner les deux côtés ne donne pas l’hypoténuse.","1,7 correspond à une soustraction directe des longueurs.","√5,27 soustrait les carrés au lieu de les additionner."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q06","prompt":"Un carré a des côtés de 5 cm. Sa diagonale mesure √50 cm. Quelle valeur arrondie au dixième de centimètre convient ?","expected":"7,1 cm","alternatives":["7,0 cm","10,0 cm","5,0 cm"],"explanation":"√50 ≈ 7,071 cm ; arrondi au dixième de centimètre : 7,1 cm.","feedback":["7,0 est trop petit : le chiffre des centièmes est 7, donc on arrondit à 7,1.","10 cm résulte d’une addition des côtés : 5 + 5.","5 cm est la mesure d’un côté du carré, pas de sa diagonale."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q07","prompt":"Un triangle est rectangle ; ses côtés de l'angle droit mesurent 7 cm et 24 cm. Quelle est l'hypoténuse ?","expected":"25 cm","alternatives":["31 cm","17 cm","√527 cm"],"explanation":"7² + 24² = 49 + 576 = 625 ; √625 = 25 cm.","feedback":["31 = 7 + 24, alors que Pythagore impose d’additionner les carrés.","17 = 24 − 7, une différence directe de côtés.","√527 correspond à 24² − 7² ; ici il faut ajouter."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q08","prompt":"Un rectangle mesure 8 m sur 15 m. Quelle est la longueur de sa diagonale ?","expected":"17 m","alternatives":["23 m","7 m","√161 m"],"explanation":"La diagonale est l'hypoténuse : d² = 8² + 15² = 289 ; d = 17 m.","feedback":["23 m est la somme 8 + 15, pas la diagonale.","7 m est la différence des deux côtés.","√161 m provient de 15² − 8² au lieu de leur somme."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q09","prompt":"Dans un triangle rectangle, l'hypoténuse mesure 13 cm et un côté mesure 5 cm. Quelle est la longueur de l'autre côté de l'angle droit ?","expected":"12 cm","alternatives":["8 cm","18 cm","√194 cm"],"explanation":"côté² = 13² − 5² = 169 − 25 = 144 ; côté = 12 cm.","feedback":["13 − 5 = 8 n’est pas la différence des carrés.","13 + 5 = 18 ne donne pas le côté manquant.","√194 additionne 13² et 5² au lieu de les soustraire."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"},{"questionId":"MT06-Q10","prompt":"Un triangle rectangle a des côtés de l'angle droit de 1,2 m et 1,6 m. Combien mesure son hypoténuse ?","expected":"2 m","alternatives":["2,8 m","0,4 m","√1,12 m"],"explanation":"h² = 1,2² + 1,6² = 1,44 + 2,56 = 4 ; h = 2 m.","feedback":["2,8 est la somme des longueurs, pas le résultat de Pythagore.","0,4 est la différence entre les côtés.","√1,12 vient de 1,6² − 1,2² ; ici il faut additionner les carrés pour l’hypoténuse."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS06"}],"MT07":[{"questionId":"MT07-Q01","prompt":"Un triangle a pour longueurs 8 cm, 15 cm et 17 cm. Est-il rectangle ?","expected":"Oui, car 8² + 15² = 17².","alternatives":["Non, car 8 + 15 ≠ 17.","Oui, car 8 + 15 > 17.","Impossible sans dessin à l’échelle."],"explanation":"8² + 15² = 64 + 225 = 289 = 17². La réciproque prouve que le triangle est rectangle.","feedback":["L’égalité à vérifier porte sur les carrés, pas sur la somme des longueurs.","L’inégalité triangulaire vérifie l’existence du triangle, pas l’angle droit.","Les longueurs données suffisent ; le dessin n’a pas besoin d’être à l’échelle."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q02","prompt":"Pour tester un triangle de côtés 5 cm, 12 cm et 13 cm, quel carré faut-il comparer à la somme des deux autres carrés ?","expected":"13²","alternatives":["5²","12²","(5 + 12)²"],"explanation":"La potentielle hypoténuse est le plus grand côté, de longueur 13 cm.","feedback":["5 cm n’est pas le plus grand côté.","12 cm n’est pas le plus grand côté.","Il faut élever au carré un côté réellement donné, pas la somme de deux côtés."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q03","prompt":"Les côtés d'un triangle mesurent 6, 8 et 10 cm. Quelle égalité démontre que le triangle est rectangle ?","expected":"6² + 8² = 10²","alternatives":["6 + 8 = 10","6² + 10² = 8²","6 × 8 = 10²"],"explanation":"6² + 8² = 36 + 64 = 100 = 10² : on peut appliquer la réciproque.","feedback":["6 + 8 = 14, et Pythagore compare des carrés.","10 cm est le plus grand côté ; son carré doit être seul.","Un produit de côtés ne remplace pas la somme de leurs carrés."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q04","prompt":"Dans le triangle MNP, MN = 8 cm, NP = 15 cm, MP = 17 cm. Après vérification de Pythagore, à quel sommet est l'angle droit ?","expected":"N","alternatives":["M","P","Impossible à déterminer"],"explanation":"Le plus long côté est [MP] : l'angle droit est au sommet opposé, N.","feedback":["M est une extrémité du côté [MP], donc l’angle droit ne peut pas être en M.","P est aussi une extrémité de [MP] ; l’angle droit est en face, à N.","Les trois longueurs et l’égalité des carrés permettent de conclure."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q05","prompt":"On connaît les trois côtés d'un triangle et on vérifie l'égalité de Pythagore. Quel résultat permet d'affirmer qu'il est rectangle ?","expected":"La réciproque de Pythagore","alternatives":["Le théorème direct de Pythagore","Le théorème de Thalès","La formule de l’aire du triangle"],"explanation":"La réciproque part des trois longueurs et prouve l'existence d'un angle droit.","feedback":["Le théorème direct suppose déjà connu l’angle droit.","Thalès concerne des rapports dans des configurations de parallèles.","L’aire ne prouve pas à elle seule qu’un triangle est rectangle."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q06","prompt":"Un triangle possède des côtés de 9 cm, 40 cm et 41 cm. Quelle conclusion est justifiée ?","expected":"Il est rectangle.","alternatives":["Il est équilatéral.","Il est nécessairement isocèle.","Il n’existe pas."],"explanation":"9² + 40² = 81 + 1600 = 1681 = 41², donc ce triangle est rectangle.","feedback":["Les côtés ont trois longueurs différentes : ils ne sont pas tous égaux.","Aucune paire de côtés n’a la même longueur ; il n’est pas isocèle.","9 + 40 > 41 : les côtés permettent bien de former un triangle."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q07","prompt":"Pour un triangle de côtés 3, 4 et 5 cm, quelle justification est mathématiquement complète ?","expected":"3² + 4² = 5² ; d’après la réciproque de Pythagore, le triangle est rectangle.","alternatives":["3 + 4 > 5 ; donc il est rectangle.","Le dessin paraît rectangle ; donc il l’est.","5 est le plus grand côté ; donc il est rectangle."],"explanation":"On établit l'égalité exacte 9 + 16 = 25, puis on cite la réciproque et la conclusion.","feedback":["3 + 4 > 5 montre seulement que le triangle peut exister.","Le dessin peut ne pas être à l’échelle : son apparence ne suffit pas.","Le plus grand côté existe dans tout triangle, même non rectangle."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q08","prompt":"Les côtés d'un triangle mesurent 7 cm, 24 cm et 25 cm. À combien vaut la somme des carrés des deux plus petits côtés ?","expected":"625 cm²","alternatives":["31 cm²","49 cm²","576 cm²"],"explanation":"7² + 24² = 49 + 576 = 625 cm², ce qui vaut aussi 25².","feedback":["31 est la somme des longueurs 7 + 24, et non des carrés.","49 est seulement 7² ; il manque 24².","576 est seulement 24² ; il manque 7²."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q09","prompt":"Un triangle a pour côtés 10 cm, 24 cm et 26 cm. Quel fait prouve qu'il est rectangle ?","expected":"26² = 10² + 24²","alternatives":["26 = 10 + 24","26² = 10 × 24","24² = 10² + 26²"],"explanation":"26² = 676 et 10² + 24² = 100 + 576 = 676 : réciproque de Pythagore.","feedback":["L’hypoténuse n’est pas la somme des deux autres longueurs.","La multiplication 10 × 24 ne donne pas la somme des carrés.","26 est la plus grande longueur : son carré doit être seul."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"},{"questionId":"MT07-Q10","prompt":"Dans un triangle ABC, AB = 12 cm, AC = 5 cm et BC = 13 cm. Quel sommet est l'angle droit ?","expected":"A","alternatives":["B","C","Aucun, ce triangle n’est pas rectangle"],"explanation":"AB² + AC² = 144 + 25 = 169 = BC². L'hypoténuse [BC] est en face du sommet A.","feedback":["Le sommet B touche le côté [BC], qui est l’hypoténuse.","Le sommet C touche lui aussi l’hypoténuse [BC].","Les carrés sont égaux : la réciproque prouve que le triangle est rectangle."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS07"}],"MT08":[{"questionId":"MT08-Q01","prompt":"Un triangle a pour côtés 4, 5 et 6 cm. Quelle comparaison permet de conclure qu'il n'est pas rectangle ?","expected":"6² = 36 et 4² + 5² = 41.","alternatives":["6² = 36 et 4² + 5² = 36.","6 = 4 + 5.","4² = 16 et 5² = 25, sans calculer leur somme."],"explanation":"6² = 36, tandis que 4² + 5² = 16 + 25 = 41. Les valeurs diffèrent.","feedback":["4² + 5² vaut 41, pas 36 : l’égalité annoncée est fausse.","4 + 5 vaut 9 : il faut comparer les carrés, pas les côtés simplement.","Les carrés séparés ne suffisent pas : il faut comparer leur somme au plus grand carré."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q02","prompt":"Les côtés d'un triangle DEF sont DE = 8 cm, DF = 11 cm et EF = 14 cm. Sachant que 8² + 11² = 185 et 14² = 196, que peut-on conclure ?","expected":"Le triangle DEF n’est pas rectangle.","alternatives":["Le triangle DEF est rectangle en D.","Le triangle DEF est rectangle en E.","On ne peut rien conclure avec ces longueurs."],"explanation":"185 est différent de 196 ; la contraposée de Pythagore prouve que le triangle n'est pas rectangle.","feedback":["Pour être rectangle en D, il faudrait EF² = DE² + DF², ce qui est faux.","Un triangle rectangle en E aurait [DF] pour hypoténuse, or [EF] est plus long.","Les trois longueurs permettent justement de tester la condition."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q03","prompt":"Quand le carré du plus grand côté est différent de la somme des deux autres carrés, quel raisonnement démontre qu'un triangle n'est pas rectangle ?","expected":"La contraposée de Pythagore","alternatives":["La réciproque de Pythagore","Le théorème de Thalès","Le calcul d’une aire"],"explanation":"La contraposée permet de conclure « non rectangle » à partir de l'absence d'égalité.","feedback":["La réciproque s’utilise lorsque les carrés sont égaux pour conclure « rectangle ».","Thalès nécessite des alignements et des parallèles.","Une aire ne remplace pas la comparaison des carrés de trois longueurs."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q04","prompt":"Un triangle possède des côtés de 5 cm, 6 cm et 8 cm. Quelle égalité serait nécessaire pour qu'il soit rectangle ?","expected":"8² = 5² + 6²","alternatives":["6² = 5² + 8²","8 = 5 + 6","5² = 6² + 8²"],"explanation":"Le plus grand côté est 8 ; on compare 64 à 25 + 36 = 61. Comme 64 ≠ 61, le triangle n'est pas rectangle.","feedback":["6 n’est pas le plus grand côté ; son carré ne doit pas être isolé.","Il faut comparer les carrés, pas une somme de longueurs.","5 n’est pas le plus grand côté ; ce serait une mauvaise hypoténuse."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q05","prompt":"Un élève écrit : « Le triangle de côtés 6, 7 et 9 cm est rectangle, car 6² + 7² = 9². » Quelle est son erreur ?","expected":"6² + 7² vaut 85, pas 81.","alternatives":["Il fallait calculer 6 + 7, pas les carrés.","Il fallait utiliser Thalès.","9 n’est pas le plus long côté."],"explanation":"6² + 7² = 36 + 49 = 85, tandis que 9² = 81 : le triangle n'est pas rectangle.","feedback":["La comparaison des carrés est bien la méthode adaptée ; c’est son résultat qui est faux.","Aucune parallèle n’est donnée, donc Thalès n’est pas le bon outil.","9 est bien le plus grand des trois côtés."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q06","prompt":"Une figure semble montrer un angle droit, mais les trois mesures ne vérifient pas Pythagore. Que faut-il faire ?","expected":"Se fier aux mesures et conclure que le triangle n’est pas rectangle.","alternatives":["Conclure rectangle parce que le dessin semble droit.","Mesurer l’angle avec une règle.","Arrondir les carrés jusqu’à obtenir une égalité."],"explanation":"Les mesures et la comparaison des carrés constituent la démonstration ; une figure peut ne pas être à l'échelle.","feedback":["L’apparence d’un dessin ne remplace pas une preuve.","Une règle mesure des longueurs, et ne prouve pas qu’un angle est droit.","On ne doit jamais fabriquer une égalité par un arrondi arbitraire."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q07","prompt":"Dans un triangle de côtés 7, 8 et 10 cm, combien vaut 7² + 8², à comparer à 10² = 100 ?","expected":"113","alternatives":["100","105","15"],"explanation":"7² + 8² = 49 + 64 = 113 ; 113 ≠ 100, donc le triangle n'est pas rectangle.","feedback":["100 est le carré du côté de 10 cm, pas la somme des deux autres carrés.","105 ne correspond pas à 49 + 64.","15 est la somme 7 + 8, alors qu’il faut élever au carré puis additionner."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q08","prompt":"Un triangle a pour côtés 5, 7 et 9 cm. On calcule 5² + 7² = 74 et 9² = 81. Quelle phrase est rigoureuse ?","expected":"Comme 74 ≠ 81, par la contraposée de Pythagore, il n’est pas rectangle.","alternatives":["Comme 5 + 7 > 9, il est rectangle.","Comme 81 > 74, il est rectangle.","On ne peut pas conclure sans connaître les angles."],"explanation":"Le carré du plus grand côté est différent de la somme des deux autres ; la contraposée donne la conclusion.","feedback":["L’inégalité triangulaire ne prouve pas l’existence d’un angle droit.","Une inégalité entre les carrés permet précisément de conclure qu’il n’est pas rectangle.","Les longueurs suffisent à conclure grâce à la contraposée."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q09","prompt":"La réciproque de Pythagore sert à prouver « rectangle ». À quoi sert la contraposée ?","expected":"À prouver « non rectangle » lorsque les carrés ne sont pas égaux.","alternatives":["À calculer un côté manquant dans un triangle rectangle.","À prouver deux droites parallèles avec des rapports.","À mesurer les angles sur le dessin."],"explanation":"On vérifie la non-égalité des carrés pour démontrer qu'un triangle n'est pas rectangle.","feedback":["Trouver un côté dans un triangle déjà rectangle relève du théorème direct.","Les rapports de Thalès concernent les parallèles, pas cette conclusion.","La méthode est un calcul exact, pas une mesure sur la figure."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"},{"questionId":"MT08-Q10","prompt":"Les côtés d'un triangle sont donnés exactement. Pourquoi vaut-il mieux comparer les carrés exacts avant d'arrondir ?","expected":"Pour éviter de conclure à tort à une égalité ou à une différence.","alternatives":["Parce qu’une égalité arrondie est toujours exacte.","Parce qu’on doit ignorer le plus grand côté.","Parce qu’un triangle peut avoir deux hypoténuses."],"explanation":"Les arrondis peuvent masquer une petite différence ; la preuve doit utiliser les valeurs exactes lorsque c'est possible.","feedback":["Deux résultats arrondis égaux ne sont pas nécessairement égaux exactement.","Le plus grand côté est celui qu’on compare à la somme des deux autres carrés.","Un triangle rectangle ne possède qu’une seule hypoténuse."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS08"}],"MT09":[{"questionId":"MT09-Q01","prompt":"Une échelle repose sur un sol horizontal et atteint un mur vertical à 1,2 m de hauteur. Son pied est à 0,9 m du mur. Quelle est sa longueur ?","expected":"1,5 m","alternatives":["2,1 m","0,3 m","√0,63 m"],"explanation":"L² = 1,2² + 0,9² = 1,44 + 0,81 = 2,25 ; L = 1,5 m.","feedback":["1,2 + 0,9 = 2,1 : ce n’est pas le calcul de l’hypoténuse.","1,2 − 0,9 = 0,3 ne calcule pas l’échelle.","√0,63 correspond à une différence des carrés, au lieu de leur somme."],"docId":"ENT-2026FicheexercicesPythagorepdf","pages":[1],"title":"2026 Fiche exercices Pythagore.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q02","prompt":"Un toboggan forme un triangle rectangle : la rampe mesure 5 m et la distance horizontale au pied du support est 3 m. Quelle est la hauteur du support ?","expected":"4 m","alternatives":["8 m","2 m","√34 m"],"explanation":"Hauteur² = 5² − 3² = 25 − 9 = 16 ; hauteur = 4 m.","feedback":["5 + 3 = 8 n’est pas la hauteur : on connaît déjà l’hypoténuse.","5 − 3 = 2 ne tient pas compte des carrés.","√34 vient de 5² + 3², mais il faut retirer le carré de 3."],"docId":"ENT-2026FicheexercicesPythagorepdf","pages":[1],"title":"2026 Fiche exercices Pythagore.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q03","prompt":"Un terrain rectangulaire mesure 30 m sur 40 m. Quelle est la distance en ligne droite entre deux coins opposés ?","expected":"50 m","alternatives":["70 m","10 m","√700 m"],"explanation":"La diagonale vaut √(30² + 40²) = √2500 = 50 m.","feedback":["70 m est la somme des côtés, pas la diagonale.","10 m est la différence des côtés.","√700 résulte de 40² − 30², alors qu’il faut additionner."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q04","prompt":"Un circuit a la forme d'un triangle rectangle dont les deux petits côtés mesurent 9 m et 12 m. Un coureur effectue 4 tours du circuit. Quelle distance parcourt-il ?","expected":"144 m","alternatives":["36 m","60 m","84 m"],"explanation":"L'hypoténuse mesure 15 m. Un tour vaut 9 + 12 + 15 = 36 m ; quatre tours valent 144 m.","feedback":["36 m est la longueur d’un seul tour, pas de quatre tours.","60 m correspond à 4 × 15 ; il manque les deux autres côtés à chaque tour.","84 m correspond à 4 × (9 + 12) ; il manque l’hypoténuse."],"docId":"ENT-2026FicheexercicesPythagorepdf","pages":[1],"title":"2026 Fiche exercices Pythagore.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q05","prompt":"Un pavé droit a pour dimensions 3 cm, 4 cm et 12 cm. La diagonale de sa base mesure 5 cm. Quelle est la grande diagonale reliant deux sommets opposés du pavé ?","expected":"13 cm","alternatives":["19 cm","12 cm","√153 cm"],"explanation":"La diagonale de base vaut 5 cm. La grande diagonale vérifie D² = 5² + 12² = 169, donc D = 13 cm.","feedback":["19 cm additionne 5 et 12, alors qu’il faut travailler avec les carrés.","12 cm est seulement la hauteur du pavé, pas sa grande diagonale.","√153 résulte de 12² + 3² et oublie le côté de base de 4 cm."],"docId":"ENT-2026FicheexercicesPythagorepdf","pages":[1],"title":"2026 Fiche exercices Pythagore.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q06","prompt":"Un poteau, le sol et un câble forment un triangle dont les côtés mesurent 3 m, 4 m et 5 m. Peut-on affirmer que le poteau est perpendiculaire au sol, si leurs longueurs sont 3 m et 4 m ?","expected":"Oui : 3² + 4² = 5².","alternatives":["Oui : 3 + 4 = 5.","Non : 3 et 4 sont différents.","Impossible à vérifier avec trois longueurs."],"explanation":"3² + 4² = 9 + 16 = 25 = 5². Par la réciproque, l'angle entre les côtés de 3 et 4 m est droit.","feedback":["3 + 4 = 7, et la réciproque compare les carrés.","Deux côtés perpendiculaires ne doivent pas nécessairement être égaux.","Les trois longueurs suffisent à établir la perpendicularité."],"docId":"ENT-2026FicheexercicesPythagorepdf","pages":[2],"title":"2026 Fiche exercices Pythagore.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q07","prompt":"Un jardin triangulaire est rectangle. Ses côtés perpendiculaires mesurent 6 m et 8 m. Quelle est son aire ?","expected":"24 m²","alternatives":["48 m²","14 m²","10 m²"],"explanation":"Aire d'un triangle rectangle = 6 × 8 ÷ 2 = 24 m².","feedback":["48 m² est l’aire du rectangle correspondant ; il faut diviser par 2.","14 m² additionne les longueurs, ce qui ne calcule pas une aire.","10 m est l’hypoténuse, une longueur, pas une aire."],"docId":"ENT-2026FicheexercicesPythagorepdf","pages":[2],"title":"2026 Fiche exercices Pythagore.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q08","prompt":"Un terrain triangulaire rectangle a pour côtés 8 m, 15 m et 17 m. Quel est son périmètre ?","expected":"40 m","alternatives":["34 m","120 m","60 m"],"explanation":"Le périmètre est la somme des trois longueurs : 8 + 15 + 17 = 40 m.","feedback":["34 m est deux fois la longueur 17 m, mais il faut additionner les trois côtés.","120 m est un produit, pas la longueur du contour.","60 m ne correspond pas à la somme des trois longueurs données."],"docId":"ENT-2026FicheexercicesPythagorepdf","pages":[2],"title":"2026 Fiche exercices Pythagore.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q09","prompt":"Un câble de 10 m relie le sommet d'un poteau vertical de 8 m à un point du sol. Le sol est horizontal. À quelle distance du pied du poteau est fixé le câble ?","expected":"6 m","alternatives":["18 m","2 m","√164 m"],"explanation":"Distance² = 10² − 8² = 100 − 64 = 36 ; distance = 6 m.","feedback":["18 m additionne les mesures de l’hypoténuse et du poteau.","2 m est une simple soustraction 10 − 8.","√164 additionne les carrés alors que le câble, hypoténuse, est connu."],"docId":"ENT-2026FicheexercicesPythagorepdf","pages":[2],"title":"2026 Fiche exercices Pythagore.pdf","lessonId":"MBIS09"},{"questionId":"MT09-Q10","prompt":"Un câble de 4,5 m doit relier deux coins opposés d'un panneau rectangulaire de 2,4 m sur 3,2 m. Le câble est-il assez long et quelle longueur restera-t-il ?","expected":"Oui, il restera 0,5 m.","alternatives":["Oui, il restera 1,3 m.","Non, car la diagonale vaut 5,6 m.","Oui, il restera 4,0 m."],"explanation":"La diagonale vaut √(2,4² + 3,2²) = √16 = 4 m ; 4,5 − 4 = 0,5 m.","feedback":["1,3 m ne correspond pas à la différence 4,5 − 4,0.","5,6 m est 2,4 + 3,2, pas la diagonale calculée.","4,0 m est la longueur nécessaire pour relier les coins, pas la marge."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS09"}],"MT10":[{"questionId":"MT10-Q01","prompt":"Dans l’expression 3x, que signifie l’écriture 3x ?","expected":"3 × x","alternatives":["3 + x","33 × x","x × x × x"],"explanation":"Le signe de multiplication est sous-entendu : 3x = 3 × x.","feedback":["3x indique une multiplication, pas une addition.","Le chiffre 3 n’est pas répété devant x : 3x vaut trois fois x, pas trente-trois fois x.","x × x × x s’écrit x³ ; cela ne correspond pas à 3x."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q02","prompt":"Réduis 4x + 3x − 2.","expected":"7x − 2","alternatives":["7x","5x","7x − 2x"],"explanation":"4x + 3x = 7x ; le nombre −2 reste à part car il ne contient pas x.","feedback":["Tu as oublié le terme constant −2 : il reste dans l’expression finale.","Tu as soustrait 2 du coefficient 7, mais un nombre sans x ne se regroupe pas avec un terme en x.","Le nombre −2 est un terme constant : il ne devient pas −2x."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q03","prompt":"Calcule 2x + 1 lorsque x = −3.","expected":"−5","alternatives":["−7","7","5"],"explanation":"2 × (−3) + 1 = −6 + 1 = −5.","feedback":["−7 correspondrait à soustraire 1 à −6, alors que la consigne demande +1.","7 vient d’une perte du signe négatif de x ; 2 × (−3) est négatif.","Le résultat vaut −5, pas +5 : garde le signe après le calcul."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q04","prompt":"Réduis 4x − 2x + 5.","expected":"2x + 5","alternatives":["2x","6x + 5","7x"],"explanation":"4x − 2x = 2x. On conserve ensuite le terme constant +5.","feedback":["Le terme +5 doit rester présent après la réduction.","Le signe devant 2x est − : il faut soustraire les coefficients 4 − 2, et non additionner.","Tu ne peux pas additionner 5 à un coefficient de x : 2x + 5 ne vaut pas 7x."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q05","prompt":"Peut-on réduire directement 2x + 3 en 5x ?","expected":"Non, car 2x et 3 ne sont pas des termes semblables.","alternatives":["Oui, parce que 2 + 3 = 5.","Oui, pour toute valeur de x.","Oui, seulement si x est négatif."],"explanation":"2x contient la lettre x et 3 est un nombre seul : ils ne peuvent pas se regrouper.","feedback":["Le calcul 2 + 3 ne peut pas s’appliquer aux coefficients lorsque l’un des termes n’a pas x.","Par exemple, avec x = 2, 2x + 3 = 7 tandis que 5x = 10 : ce n’est pas équivalent.","Le signe de x ne change pas la nature de 2x et du terme constant 3."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q06","prompt":"Calcule x² − 3x lorsque x = −2.","expected":"10","alternatives":["−2","−10","2"],"explanation":"(−2)² − 3 × (−2) = 4 + 6 = 10.","feedback":["−2 est la valeur donnée à x, et non le résultat de l’expression.","(−2)² vaut +4, et −3 × (−2) vaut +6 : le résultat n’est pas négatif.","Tu as oublié le produit −3 × (−2), qui ajoute 6 au carré de x."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q07","prompt":"Réduis 5a + 2a − 3a.","expected":"4a","alternatives":["10a","0a","4a²"],"explanation":"Les termes sont tous en a : (5 + 2 − 3)a = 4a.","feedback":["Il faut soustraire 3a : 5 + 2 − 3 = 4, pas 10.","Les coefficients ne s’annulent pas : 5 + 2 − 3 vaut 4.","Additionner des termes en a ne change pas la puissance de la lettre : le résultat reste en a."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q08","prompt":"Réduis 2x + 3x² − x.","expected":"3x² + x","alternatives":["4x²","4x","3x² + 3x"],"explanation":"2x − x = x ; le terme 3x² reste séparé car x² et x sont différents.","feedback":["Les termes x et x² ne sont pas semblables : tu ne peux pas tout regrouper en x².","Tu ne peux pas transformer 3x² en 3x : les degrés sont différents.","Tu as oublié de retirer x des 2x initiaux : 2x − x = x."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q09","prompt":"Calcule 2a + 3b lorsque a = −1 et b = 4.","expected":"10","alternatives":["14","−10","5"],"explanation":"2 × (−1) + 3 × 4 = −2 + 12 = 10.","feedback":["14 vient de +2 + 12 : tu as perdu le signe négatif de a.","La somme de −2 et +12 est positive : elle vaut 10.","Il faut multiplier chaque lettre par son coefficient avant d’additionner les résultats."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"},{"questionId":"MT10-Q10","prompt":"Quelle expression représente « le triple de x, puis on retire 5 » ?","expected":"3x − 5","alternatives":["3(x − 5)","x − 15","3x + 5"],"explanation":"Le triple de x est 3x ; retirer 5 après cela donne 3x − 5.","feedback":["3(x − 5) signifie retirer 5 AVANT de tripler : cela correspond à une autre consigne.","Tu as retranché 15 à x : cela ne représente pas le triple du nombre de départ.","Retirer 5 demande une soustraction, et non une addition."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS10"}],"MT11":[{"questionId":"MT11-Q01","prompt":"Développe 4(2x − 3).","expected":"8x − 12","alternatives":["8x − 3","6x − 12","8x + 12"],"explanation":"4 × 2x = 8x et 4 × (−3) = −12 ; les deux termes sont multipliés.","feedback":["Le 4 doit multiplier −3 également ; 4 × (−3) = −12.","4 × 2x fait 8x, et non 6x : on multiplie les coefficients.","4 × (−3) est négatif : le signe de −12 doit être conservé."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1,2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q02","prompt":"Réduis 7x − (3x + 5).","expected":"4x − 5","alternatives":["4x + 5","10x − 5","4x"],"explanation":"7x − (3x + 5) = 7x − 3x − 5 = 4x − 5.","feedback":["Le signe moins devant la parenthèse change +5 en −5.","Tu dois retirer 3x à 7x, pas ajouter 3x.","Le terme constant −5 ne disparaît pas."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1,2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q03","prompt":"Développe 3(x + 5).","expected":"3x + 15","alternatives":["3x + 5","8x","3x − 15"],"explanation":"3(x + 5) = 3 × x + 3 × 5 = 3x + 15.","feedback":["Le nombre 5 doit aussi être multiplié par 3 : on obtient +15.","x est une lettre ; on ne peut pas additionner x à 5 avant d’avoir une valeur de x.","3 × (+5) donne +15, pas −15. Revois les étapes du calcul."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q04","prompt":"Développe −2(x + 4).","expected":"−2x − 8","alternatives":["−2x + 8","2x − 8","−2x − 4"],"explanation":"−2 × x = −2x et −2 × (+4) = −8.","feedback":["Un nombre négatif multiplié par un nombre positif donne un nombre négatif.","Le facteur devant x est −2, pas +2 : il faut conserver son signe.","Le terme +4 doit être multiplié par −2 : on obtient −8, pas −4."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q05","prompt":"Enlève les parenthèses dans −(x − 7).","expected":"−x + 7","alternatives":["−x − 7","x + 7","x − 7"],"explanation":"−(x − 7) = (−1) × x + (−1) × (−7) = −x + 7.","feedback":["Le signe moins devant la parenthèse change le signe de chaque terme, y compris −7.","Le signe devant x doit également être changé : x devient −x.","Oublier le signe moins extérieur revient à ne pas effectuer l’opération demandée."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q06","prompt":"Développe et réduis 5(2x − 1) − 3x.","expected":"7x − 5","alternatives":["10x − 5","7x + 5","7x − 1"],"explanation":"5(2x − 1) − 3x = 10x − 5 − 3x = 7x − 5.","feedback":["Tu as oublié le terme −3x lors de la réduction finale.","5 × (−1) = −5, et non +5. Revois les étapes du calcul.","Tu as oublié de multiplier −1 par 5, ce qui donne −5."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q07","prompt":"Développe 2(3 − 4x).","expected":"6 − 8x","alternatives":["6 − 4x","6 + 8x","5 − 8x"],"explanation":"2 × 3 = 6 et 2 × (−4x) = −8x.","feedback":["Le facteur 2 multiplie aussi le terme −4x.","Le produit 2 × (−4x) reste négatif : −8x.","2 × 3 vaut 6, pas 5. Revois les étapes du calcul."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q08","prompt":"Développe −3(2x − 5).","expected":"−6x + 15","alternatives":["−6x − 15","6x + 15","−6x + 5"],"explanation":"−3 × 2x = −6x ; (−3) × (−5) = +15.","feedback":["Le produit de deux nombres négatifs est positif : +15.","−3 × 2x = −6x : le coefficient de x doit rester négatif.","Le terme −5 est multiplié par −3 ; cela donne +15 et non +5."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q09","prompt":"Réduis (4x + 1) − (x − 2).","expected":"3x + 3","alternatives":["3x − 1","5x − 1","3x − 3"],"explanation":"4x + 1 − x + 2 = 3x + 3 : le signe moins change les signes de la deuxième parenthèse.","feedback":["Le −(−2) donne +2, donc les constantes valent 1 + 2 = 3.","On soustrait x à 4x : 4x − x = 3x, pas 5x.","Le signe devant −2 change : la constante finale est +3, pas −3."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"},{"questionId":"MT11-Q10","prompt":"Développe et réduis 6 − 2(x − 3).","expected":"12 − 2x","alternatives":["−2x","6 − 2x − 3","12 + 2x"],"explanation":"6 − 2(x − 3) = 6 − 2x + 6 = 12 − 2x.","feedback":["Tu as oublié d’ajouter la constante +6 provenant de −2 × (−3).","Tu n’as pas distribué le −2 au terme −3 ; le produit vaut +6.","Le produit −2 × x vaut −2x, pas +2x."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS11"}],"MT12":[{"questionId":"MT12-Q01","prompt":"Développe et réduis (x − 3)(x + 1).","expected":"x² − 2x − 3","alternatives":["x² + 4x − 3","x² − 3","x² − 2x + 3"],"explanation":"(x − 3)(x + 1) = x² + x − 3x − 3 = x² − 2x − 3.","feedback":["Les termes en x sont +x et −3x : ensemble ils donnent −2x, pas +4x.","Le développement comporte quatre produits : tu as oublié les deux produits qui créent des termes en x.","(−3) × (+1) = −3 : le terme constant n’est pas +3."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q02","prompt":"Développe et réduis (x − 4)(x − 7).","expected":"x² − 11x + 28","alternatives":["x² − 11x − 28","x² + 11x + 28","x² − 28"],"explanation":"x² − 7x − 4x + 28 = x² − 11x + 28.","feedback":["(−4) × (−7) = +28, parce que les deux facteurs sont négatifs.","Les deux produits en x sont négatifs : −7x − 4x = −11x.","Les termes −7x et −4x ne peuvent pas disparaître lors de la réduction."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q03","prompt":"Développe et réduis (x + 2)(x + 5).","expected":"x² + 7x + 10","alternatives":["x² + 10","x² + 3x + 10","x² + 7x − 10"],"explanation":"x×x + x×5 + 2×x + 2×5 = x² + 5x + 2x + 10 = x² + 7x + 10.","feedback":["Il manque les deux produits croisés 5x et 2x.","Les produits croisés valent 5x + 2x = 7x, et non 3x.","(+2) × (+5) vaut +10 ; le dernier terme est positif."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q04","prompt":"Développe et réduis (x − 2)(x + 6).","expected":"x² + 4x − 12","alternatives":["x² + 8x − 12","x² + 4x + 12","x² − 4x − 12"],"explanation":"x² + 6x − 2x − 12 = x² + 4x − 12.","feedback":["Les termes croisés sont +6x et −2x : leur somme vaut +4x, pas +8x.","(−2) × (+6) = −12 : le terme constant est négatif.","+6x − 2x donne +4x, pas −4x. Revois les étapes du calcul."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q05","prompt":"Développe et réduis (2x + 1)(x + 3).","expected":"2x² + 7x + 3","alternatives":["2x² + 6x + 3","2x² + 7x","2x² + 7x + 1"],"explanation":"2x·x + 2x·3 + 1·x + 1·3 = 2x² + 6x + x + 3 = 2x² + 7x + 3.","feedback":["Tu as oublié le produit 1 × x : il ajoute +x, donc 6x + x = 7x.","Le produit 1 × 3 donne +3 ; le terme constant ne disparaît pas.","Le terme constant est 1 × 3 = 3 et non 1."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q06","prompt":"Développe et réduis (3x − 2)(x − 4).","expected":"3x² − 14x + 8","alternatives":["3x² − 10x + 8","3x² − 14x − 8","3x² + 14x + 8"],"explanation":"3x² − 12x − 2x + 8 = 3x² − 14x + 8.","feedback":["Les deux produits croisés sont −12x et −2x : ils donnent −14x.","(−2) × (−4) donne +8, pas −8. Revois les étapes du calcul.","Les produits croisés sont négatifs ; leur somme vaut −14x."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q07","prompt":"Développe et réduis (x − 5)(x − 2).","expected":"x² − 7x + 10","alternatives":["x² + 7x + 10","x² − 7x − 10","x² − 3x + 10"],"explanation":"x² − 2x − 5x + 10 = x² − 7x + 10.","feedback":["Les deux termes croisés sont négatifs : leur somme est −7x.","Le produit de −5 par −2 est positif : +10.","−2x − 5x donne −7x, pas −3x. Revois les étapes du calcul."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q08","prompt":"Développe et réduis (2x − 3)(x + 2).","expected":"2x² + x − 6","alternatives":["2x² + 7x − 6","2x² + x + 6","2x² − x − 6"],"explanation":"2x² + 4x − 3x − 6 = 2x² + x − 6.","feedback":["Les produits croisés sont +4x et −3x ; leur somme est +x, pas +7x.","(−3) × (+2) vaut −6 et non +6.","+4x − 3x vaut +x ; attention au signe du coefficient."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q09","prompt":"Développe et réduis (x + 3)(x − 3).","expected":"x² − 9","alternatives":["x² + 9","x² − 6x − 9","2x² − 9"],"explanation":"x² − 3x + 3x − 9 = x² − 9 : les deux termes en x s’annulent.","feedback":["(+3) × (−3) donne −9, pas +9. Revois les étapes du calcul.","−3x et +3x s’annulent : il ne reste pas de terme en x.","x × x vaut un seul x² ; on ne crée pas deux x² en développant ces binômes."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"},{"questionId":"MT12-Q10","prompt":"Développe et réduis (2x + 3)(3x − 1).","expected":"6x² + 7x − 3","alternatives":["6x² + 11x − 3","6x² + 7x + 3","5x² + 7x − 3"],"explanation":"2x·3x = 6x² ; 2x·(−1) = −2x ; 3·3x = +9x ; 3·(−1)=−3. Total : 6x² + 7x − 3.","feedback":["Les termes croisés valent −2x et +9x, donc +7x, pas +11x.","(+3) × (−1) donne −3 et non +3.","2x × 3x donne 6x² : on multiplie les coefficients 2 et 3."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS12"}],"MT13":[{"questionId":"MT13-Q01","prompt":"Programme : choisir x, retirer 2, puis multiplier le résultat par 5. Quelle expression représente le résultat ?","expected":"5(x − 2)","alternatives":["5x − 2","x − 10","5x + 2"],"explanation":"Après la soustraction, on a x − 2. Multiplier LE RÉSULTAT par 5 impose 5(x − 2).","feedback":["L’expression 5x − 2 multiplie seulement x ; elle ne multiplie pas le −2.","x − 10 ne multiplie pas le nombre de départ par 5.","La première étape est une soustraction de 2, et non une addition."],"docId":"ENT-2026exercicescalcullitteraletprogde","pages":[1,2],"title":"2026 exercices calcul littéral et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q02","prompt":"Programme : choisir x, retirer 2, multiplier le résultat par 5, puis ajouter trois fois le nombre de départ. Quelle expression réduite obtient-on ?","expected":"8x − 10","alternatives":["8x − 2","5x + 1","2x − 10"],"explanation":"5(x − 2) + 3x = 5x − 10 + 3x = 8x − 10.","feedback":["Le 5 multiplie également −2 : le terme constant vaut −10.","La dernière étape ajoute 3x, pas 3 ; développe d’abord la parenthèse.","Après développement, 5x + 3x donne 8x et non 2x."],"docId":"ENT-2026exercicescalcullitteraletprogde","pages":[1,2],"title":"2026 exercices calcul littéral et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q03","prompt":"Programme : choisir x, ajouter 4, puis doubler le résultat. Quelle est l’expression correcte ?","expected":"2(x + 4)","alternatives":["2x + 4","x + 8","2x − 4"],"explanation":"On calcule d’abord x + 4, puis on multiplie tout par 2 : 2(x + 4).","feedback":["2x + 4 ne double pas le +4 : le résultat attendu est 2x + 8.","x + 8 ne double pas le nombre x de départ.","Il faut ajouter 4 avant de doubler : ne change pas le + en −."],"docId":"ENT-2026exercicescalcullitteraletprogde","pages":[1,2],"title":"2026 exercices calcul littéral et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q04","prompt":"Programme : choisir x, le multiplier par 3, puis ajouter 7. Quelle expression obtient-on ?","expected":"3x + 7","alternatives":["3(x + 7)","x + 21","3x − 7"],"explanation":"Multiplier x par 3 donne 3x ; ajouter 7 après donne 3x + 7.","feedback":["3(x + 7) ajoute 7 AVANT la multiplication : il donnerait 3x + 21.","x + 21 ne multiplie pas x par 3 comme demandé.","La dernière étape est une addition de 7, pas une soustraction."],"docId":"ENT-2026exercicescalcullitteraletprogde","pages":[1,2],"title":"2026 exercices calcul littéral et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q05","prompt":"Programme : choisir x, ajouter 5, multiplier le résultat par 2, puis soustraire 4. Quelle est l’expression réduite ?","expected":"2x + 6","alternatives":["2x + 1","2x + 10","2x − 6"],"explanation":"2(x + 5) − 4 = 2x + 10 − 4 = 2x + 6.","feedback":["Il faut multiplier +5 par 2 avant de soustraire 4 : 10 − 4 = 6.","Tu as oublié la dernière étape « soustraire 4 ».","La constante finale vaut +6, car 10 − 4 = +6."],"docId":"ENT-2026exercicescalcullitteraletprogde","pages":[1,2],"title":"2026 exercices calcul littéral et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q06","prompt":"Programme : choisir x, ajouter 3, puis élever le résultat au carré. Si x = −2, quel résultat obtient-on ?","expected":"1","alternatives":["−1","7","−4"],"explanation":"On calcule (x + 3)². Pour x = −2 : (−2 + 3)² = 1² = 1.","feedback":["Le carré de +1 est +1 : un carré ne devient pas négatif.","Tu as élevé x au carré avant d’ajouter 3 ; l’ordre demandé est d’abord « ajouter 3 ».","Le nombre de départ est −2, mais le carré doit être calculé après l’addition de 3."],"docId":"ENT-2026exercicescalcullitteraletprogde","pages":[1,2],"title":"2026 exercices calcul littéral et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q07","prompt":"Programme : choisir x, multiplier le nombre par 4, puis retirer deux fois le nombre de départ. Quelle expression réduite ?","expected":"2x","alternatives":["2","6x","4x − 2"],"explanation":"On calcule 4x − 2x = 2x : les deux termes dépendent du nombre de départ.","feedback":["On retranche 2x, pas le nombre constant 2 : il reste un terme en x.","La deuxième étape est une soustraction de 2x ; 4x − 2x ≠ 6x.","Retirer deux fois le nombre de départ signifie −2x, pas −2."],"docId":"ENT-2026exercicescalcullitteraletprogde","pages":[1,2],"title":"2026 exercices calcul littéral et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q08","prompt":"Programme : choisir x, retirer 3, multiplier le résultat par 2, puis ajouter 6. Quelle expression réduite obtient-on ?","expected":"2x","alternatives":["2x − 6","2x + 6","x"],"explanation":"2(x − 3) + 6 = 2x − 6 + 6 = 2x.","feedback":["Il faut tenir compte de la dernière addition de 6 : elle annule le −6.","Tu as oublié de soustraire 3 avant la multiplication : 2 × (−3) = −6.","Le coefficient de x après multiplication par 2 reste 2, et non 1."],"docId":"ENT-2026exercicescalcullitteraletprogde","pages":[1,2],"title":"2026 exercices calcul littéral et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q09","prompt":"Programme A : ajouter 2 à x, puis multiplier le résultat par 3. Programme B : multiplier x par 3, puis ajouter 2. Pour x = 4, quels résultats obtient-on ?","expected":"A = 18 ; B = 14","alternatives":["A = 14 ; B = 18","A = 18 ; B = 18","A = 12 ; B = 14"],"explanation":"A = 3(4 + 2) = 18 ; B = 3 × 4 + 2 = 14. L’ordre des opérations change le résultat.","feedback":["Tu as inversé les deux programmes : A inclut 2 AVANT la multiplication.","Les deux programmes ne sont pas équivalents : le +2 est multiplié par 3 dans A seulement.","A = 3 × 6 = 18 ; 12 ne compte pas l’addition préalable de 2."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3,4],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS13"},{"questionId":"MT13-Q10","prompt":"Programme : choisir x, le multiplier par 3, retirer 1, puis doubler le résultat obtenu. Quelle expression réduite ?","expected":"6x − 2","alternatives":["6x − 1","3x − 2","6x + 2"],"explanation":"Après les deux premières opérations, on a 3x − 1. Doubler ce résultat donne 2(3x − 1) = 6x − 2.","feedback":["Doubler le résultat multiplie aussi le terme constant −1, qui devient −2.","Tu as oublié de doubler 3x : son coefficient final doit être 6.","Le nombre −1, multiplié par +2, donne −2, pas +2."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3,4],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS13"}],"MT14":[{"questionId":"MT14-Q01","prompt":"Dans le triangle ABC, M est sur [AB] et N sur [AC]. Quelle information supplémentaire permet d’appliquer le théorème de Thalès ?","expected":"Les droites (MN) et (BC) sont parallèles.","alternatives":["Le triangle ABC possède deux côtés égaux.","Les droites (AB) et (AC) sont perpendiculaires.","La longueur AM est égale à AN."],"explanation":"Les points sont déjà alignés sur les côtés du triangle. Il faut également (MN) parallèle à (BC) pour écrire les trois rapports de Thalès.","feedback":["Deux côtés égaux ne garantissent pas le parallélisme de (MN) et (BC) : ce n’est pas la condition de Thalès.","Un angle droit concerne plutôt Pythagore ; il ne remplace pas les droites parallèles nécessaires à Thalès.","AM = AN peut former un triangle isocèle, mais cela ne démontre pas que (MN) est parallèle à (BC)."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q02","prompt":"Les points M, A, B sont alignés et les points N, A, C sont alignés, avec A entre M et B et entre N et C. On sait (MN) ∥ (BC). Quelle configuration reconnais-tu ?","expected":"Une configuration papillon de Thalès.","alternatives":["Un triangle rectangle de Pythagore.","Deux triangles sans lien de proportionnalité.","Une configuration interdite pour Thalès."],"explanation":"Les deux triangles ont le sommet A commun, de part et d’autre de A. Les segments parallèles permettent d’utiliser Thalès en papillon.","feedback":["Aucun angle droit n’est donné : la situation ne demande pas directement Pythagore.","Le parallélisme de (MN) et (BC) relie les côtés correspondants des triangles par Thalès.","Thalès fonctionne aussi lorsque les triangles sont de part et d’autre du sommet commun : c’est le papillon."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q03","prompt":"M appartient à [AB] et N à [AC]. Le dessin semble montrer (MN) parallèle à (BC), mais aucun parallélisme n’est indiqué ni démontré. Peut-on appliquer Thalès avec certitude ?","expected":"Non, il manque une justification du parallélisme.","alternatives":["Oui, l’apparence du dessin suffit.","Oui, dès que M et N sont placés sur les côtés.","Oui, à condition que AB soit le plus grand côté."],"explanation":"Un dessin, même bien tracé, ne suffit pas à établir que deux droites sont parallèles. Il faut que ce soit donné ou démontré.","feedback":["L’aspect visuel ne prouve pas un parallélisme ; on doit utiliser une propriété ou une donnée de l’énoncé.","L’alignement est nécessaire mais ne suffit pas : Thalès exige aussi les parallèles.","La longueur de AB ne peut pas remplacer le parallélisme requis pour appliquer le théorème."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q04","prompt":"Dans une configuration papillon, les droites (MB) et (NC) se coupent en A ; (MN) est parallèle à (BC). Quel point est le sommet commun des triangles AMN et ABC ?","expected":"A","alternatives":["M","B","N"],"explanation":"Les deux triangles se forment à partir du point d’intersection A, d’où partent les côtés correspondants AM/AB et AN/AC.","feedback":["M est un sommet du petit triangle mais pas du grand triangle ABC : le sommet commun est A.","B appartient au grand triangle ABC, pas au petit triangle AMN ; le point commun est A.","N appartient au petit triangle mais pas au triangle ABC ; le sommet commun est A."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q05","prompt":"Dans les triangles AMN et ABC, avec M sur [AB], N sur [AC] et (MN) ∥ (BC), quel côté correspond à [MN] ?","expected":"[BC]","alternatives":["[AB]","[AC]","[AN]"],"explanation":"[MN] est le segment parallèle à [BC]. Ce sont les deux côtés correspondants des triangles AMN et ABC.","feedback":["[AB] correspond à [AM] ; il ne correspond pas au segment parallèle [MN].","[AC] correspond à [AN] ; il ne correspond pas au segment parallèle [MN].","[AN] est l’un des côtés du petit triangle ; il correspond à [AC], pas à [MN]."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q06","prompt":"Un triangle est rectangle et deux de ses côtés sont connus, mais aucun parallélisme n’est donné. Quel théorème permet de calculer le troisième côté ?","expected":"Le théorème de Pythagore.","alternatives":["Le théorème de Thalès.","La réciproque de Thalès.","La contraposée de Thalès."],"explanation":"Pythagore relie les trois côtés d’un triangle dont on sait qu’il est rectangle. Thalès nécessite des alignements et des parallèles.","feedback":["Thalès ne s’applique pas simplement parce qu’un triangle est rectangle : les parallèles ne sont pas indiquées.","La réciproque de Thalès sert à démontrer le parallélisme, pas à trouver le troisième côté d’un triangle rectangle.","La contraposée de Thalès sert à montrer que des droites ne sont pas parallèles, pas à calculer ce côté."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q07","prompt":"Dans le triangle XYZ, P est sur [XY], Q sur [XZ] et (PQ) ∥ (YZ). Quels sont les deux triangles dont les côtés sont proportionnels ?","expected":"XPQ et XYZ.","alternatives":["XYZ et YZQ.","XPY et XQZ.","XPQ et PYZ."],"explanation":"Les triangles XPQ (petit) et XYZ (grand) ont le sommet X commun ; les côtés [PQ] et [YZ] sont parallèles.","feedback":["Le triangle YZQ ne partage pas le sommet X avec XPQ et n’est pas le triangle de la configuration annoncée.","XPY et XQZ sont des groupes de points alignés et ne forment pas ici les deux triangles attendus.","PYZ n’est pas le grand triangle qui part du sommet commun X ; il faut prendre XYZ."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q08","prompt":"Les points A, M, B sont alignés dans le même ordre que A, N, C ; on a vérifié AM/AB = AN/AC. Quelle propriété sert à démontrer que (MN) ∥ (BC) ?","expected":"La réciproque de Thalès.","alternatives":["Le théorème direct de Pythagore.","La contraposée de Thalès.","La formule de l’aire du triangle."],"explanation":"Des rapports égaux et des points alignés dans le même ordre permettent de conclure au parallélisme par la réciproque de Thalès.","feedback":["Pythagore relie des longueurs dans un triangle rectangle ; il ne permet pas cette conclusion de parallélisme.","La contraposée de Thalès intervient lorsque les deux rapports ne sont pas égaux, contrairement à l’énoncé.","La formule de l’aire donne une surface, pas une démonstration que deux droites sont parallèles."],"docId":"ENT-leconTheoremedeThalespdf","pages":[3],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q09","prompt":"A, M, B sont alignés et A, N, C sont alignés. On trouve AM/AB = 2/5 et AN/AC = 3/5. Que peux-tu conclure ?","expected":"(MN) et (BC) ne sont pas parallèles.","alternatives":["(MN) et (BC) sont parallèles.","Les triangles sont forcément rectangles.","Il manque une aire pour conclure."],"explanation":"Les rapports 2/5 et 3/5 sont différents. Si (MN) et (BC) étaient parallèles, Thalès imposerait leur égalité : elles ne le sont donc pas.","feedback":["Le parallélisme imposerait 2/5 = 3/5, ce qui est faux ; la conclusion proposée contredit les calculs.","Une inégalité de rapports ne prouve pas un angle droit : elle interdit seulement le parallélisme étudié.","Aucune aire n’est nécessaire : l’inégalité des deux rapports suffit pour la contraposée."],"docId":"ENT-leconTheoremedeThalespdf","pages":[3],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"},{"questionId":"MT14-Q10","prompt":"Dans deux triangles sans alignements établis, on mesure deux rapports de longueurs égaux. Peut-on affirmer que deux côtés sont parallèles par la réciproque de Thalès ?","expected":"Non, les alignements et l’ordre des points doivent être vérifiés.","alternatives":["Oui, deux rapports égaux suffisent toujours.","Oui, si les rapports sont inférieurs à 1.","Oui, si les triangles ont la même aire."],"explanation":"La réciproque de Thalès nécessite une configuration précise et des alignements dans le même ordre ; l’égalité numérique seule ne suffit pas.","feedback":["L’égalité de nombres ne détermine pas la position des points : elle ne prouve donc pas à elle seule le parallélisme.","Un rapport inférieur à 1 ne remplace pas les conditions d’alignement demandées par la réciproque.","La comparaison des aires n’est pas une hypothèse suffisante pour la réciproque de Thalès."],"docId":"ENT-leconTheoremedeThalespdf","pages":[3],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS14"}],"MT15":[{"questionId":"MT15-Q01","prompt":"Dans le triangle ABC, M est sur [AB], N sur [AC] et (MN) ∥ (BC). AM = 1,6 cm, AN = 2,4 cm et AC = 6 cm. Calcule AB.","expected":"4 cm","alternatives":["2,4 cm","9 cm","3,2 cm"],"explanation":"Thalès : AM/AB = AN/AC, soit 1,6/AB = 2,4/6. Donc AB = 1,6 × 6 ÷ 2,4 = 4 cm.","feedback":["2,4 cm est la longueur de AN ; ce n’est pas la longueur AB recherchée dans le rapport.","9 cm correspond à une mauvaise inversion du produit en croix : la formule est AM × AC / AN.","3,2 cm est seulement le double de AM : ce facteur 2 n’est pas le coefficient de la figure."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q02","prompt":"Dans le triangle ABC, M est sur [AB], N sur [AC] et (MN) ∥ (BC). AN = 2,4 cm, AC = 6 cm et BC = 5 cm. Calcule MN.","expected":"2 cm","alternatives":["12,5 cm","5 cm","3 cm"],"explanation":"Thalès : MN/BC = AN/AC, donc MN = 5 × 2,4 ÷ 6 = 2 cm.","feedback":["12,5 cm inverse le rapport 2,4/6 ; le petit segment MN doit être plus petit que BC ici.","5 cm est la longueur de BC, pas celle de MN : le coefficient de réduction vaut 0,4.","3 cm vient d’un calcul qui n’applique pas correctement le coefficient 2,4/6 = 0,4."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q03","prompt":"Dans ABC, M est sur [AB], N sur [AC] et (MN) ∥ (BC). AM = 3 cm, AB = 9 cm et AN = 4 cm. Calcule AC.","expected":"12 cm","alternatives":["6 cm","3 cm","27 cm"],"explanation":"AM/AB = AN/AC : 3/9 = 4/AC ; donc AC = 4 × 9 ÷ 3 = 12 cm.","feedback":["6 cm ne respecte pas l’égalité 3/9 = 4/AC : le grand côté vaut trois fois le petit.","3 cm est le segment AM, pas le segment AC recherché : il faut utiliser le rapport 3/9.","27 cm utilise mal le coefficient d’agrandissement ; on doit calculer 4 × 9/3, pas 9 × 3."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q04","prompt":"Dans le triangle ABC, M est sur [AB], N sur [AC] et (MN) ∥ (BC). AM = 4 cm, AB = 10 cm et BC = 15 cm. Calcule MN.","expected":"6 cm","alternatives":["21 cm","4 cm","37,5 cm"],"explanation":"MN/BC = AM/AB = 4/10 ; donc MN = 15 × 4 ÷ 10 = 6 cm.","feedback":["21 cm additionne des valeurs sans appliquer le rapport de proportionnalité 4/10.","4 cm reprend la longueur AM, qui ne correspond pas directement à la longueur du segment MN.","37,5 cm inverse 4/10 : MN doit valoir 40 % de BC, pas 250 % de BC."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q05","prompt":"Dans le triangle ABC, M appartient à [AB], N à [AC] et (MN) ∥ (BC). MN = 4 cm, BC = 10 cm et AM = 5 cm. Calcule AB.","expected":"12,5 cm","alternatives":["8 cm","2 cm","25 cm"],"explanation":"AM/AB = MN/BC = 4/10 ; AB = AM × 10/4 = 5 × 10/4 = 12,5 cm.","feedback":["8 cm résulte d’une mauvaise utilisation des données : AB doit être 2,5 fois AM, et non 1,6 fois.","2 cm est inférieur à AM alors que M appartient à [AB] : AB ne peut pas être plus petit que 5 cm.","25 cm reviendrait à multiplier AM par 5 au lieu du coefficient 10/4 = 2,5."],"docId":"ENT-exercicesapplicationdirectepdf","pages":[1],"title":"exercices application directe.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q06","prompt":"Dans une configuration de Thalès, MN/BC = 2/3 et BC = 15 cm. Calcule MN.","expected":"10 cm","alternatives":["22,5 cm","5 cm","12 cm"],"explanation":"MN = BC × 2/3 = 15 × 2/3 = 10 cm. On conserve le rapport petit/grand.","feedback":["22,5 cm vient de l’inversion du rapport en 3/2, alors que le rapport demandé est 2/3.","5 cm correspond à un seul tiers de 15 ; il faut prendre deux tiers, donc 10 cm.","12 cm correspond à quatre cinquièmes ; le rapport indiqué est deux tiers, pas 4/5."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q07","prompt":"Dans une configuration papillon, A, O, C sont alignés dans cet ordre, B, O, D aussi, et (AB) ∥ (CD). On donne OA = 3 cm, OC = 9 cm et OB = 4 cm. Calcule OD.","expected":"12 cm","alternatives":["6 cm","3 cm","9 cm"],"explanation":"Thalès en papillon : OA/OC = OB/OD, donc 3/9 = 4/OD ; OD = 4 × 9 ÷ 3 = 12 cm.","feedback":["6 cm ne vérifie pas 3/9 = 4/OD ; on doit agrandir OB trois fois pour obtenir OD.","3 cm est OA, déjà connu : OD est un côté correspondant sur l’autre droite sécante.","9 cm est OC, pas OD : les longueurs de côtés correspondants ne sont pas forcément identiques."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q08","prompt":"Dans ABC, M appartient à [AB], N à [AC], (MN) ∥ (BC). On donne AM = 2,5 cm, AB = 5 cm et BC = 7 cm. Calcule MN.","expected":"3,5 cm","alternatives":["14 cm","2,5 cm","5 cm"],"explanation":"MN/BC = AM/AB = 2,5/5 = 0,5 ; MN = 7 × 0,5 = 3,5 cm.","feedback":["14 cm inverse le coefficient 0,5 : le segment parallèle du petit triangle ne peut pas ici valoir le double de BC.","2,5 cm est la longueur AM ; elle ne donne pas directement la longueur MN sur l’autre direction.","5 cm est la longueur AB : Thalès demande MN = 7 × 2,5/5 = 3,5 cm."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q09","prompt":"Dans ABC, M est sur [AB], N sur [AC] et (MN) ∥ (BC). AM = 6 cm, AB = 15 cm, AC = 20 cm. Calcule AN.","expected":"8 cm","alternatives":["12 cm","10 cm","50 cm"],"explanation":"AN/AC = AM/AB = 6/15 ; AN = 20 × 6/15 = 8 cm.","feedback":["12 cm ne correspond pas au coefficient 6/15 = 0,4 : on doit obtenir 40 % de 20.","10 cm est la moitié de AC, alors que le rapport AM/AB vaut 6/15, pas 1/2.","50 cm inverse le rapport ; AN, intérieur au côté [AC], doit être inférieur à AC."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"},{"questionId":"MT15-Q10","prompt":"Dans deux triangles correspondants de Thalès, MN/BC = 3/4. Si AN = 9 cm et AC correspond à AN, calcule AC.","expected":"12 cm","alternatives":["6,75 cm","3 cm","36 cm"],"explanation":"AN/AC = MN/BC = 3/4 ; donc AC = 9 × 4/3 = 12 cm.","feedback":["6,75 cm revient à réduire AN une deuxième fois au lieu de trouver la grande longueur AC.","3 cm ne conserve pas le rapport 3/4 : AC doit être 4/3 fois AN.","36 cm multiplie AN par 4 sans tenir compte du numérateur 3 dans le rapport."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS15"}],"MT16":[{"questionId":"MT16-Q01","prompt":"Dans ABC, M est sur [AB], N sur [AC] et (MN) ∥ (BC). Quelle égalité écrit correctement les trois rapports de Thalès ?","expected":"AM/AB = AN/AC = MN/BC","alternatives":["AB/AM = AN/AC = BC/MN","AM/AC = AN/AB = MN/BC","AM/AB = AC/AN = MN/BC"],"explanation":"Les segments correspondants sont AM et AB, AN et AC, MN et BC : on écrit toujours petit/grand dans chaque rapport.","feedback":["Tu as inversé le premier et le troisième rapports, mais pas celui du milieu : les trois doivent avoir le même sens.","AM correspond à AB et AN à AC : tu as croisé des côtés qui ne se correspondent pas.","AC/AN inverse uniquement le rapport central ; il faut conserver la même orientation dans les trois fractions."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q02","prompt":"Dans ABC, M est sur [AB], N sur [AC] et (MN) ∥ (BC). Quelle égalité est correcte si l’on inverse tous les rapports de Thalès ?","expected":"AB/AM = AC/AN = BC/MN","alternatives":["AB/AM = AN/AC = BC/MN","AM/AB = AC/AN = BC/MN","AB/AN = AC/AM = BC/MN"],"explanation":"On peut choisir grand/petit, à condition d’inverser les trois fractions : AB/AM = AC/AN = BC/MN.","feedback":["Le rapport AN/AC n’est pas inversé, alors que le premier et le troisième le sont.","Le premier rapport reste petit/grand, tandis que les autres sont inversés : on mélange les sens.","AB ne correspond pas à AN ; il faut associer AB à AM et AC à AN."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q03","prompt":"Dans XYZ, P est sur [XY], Q sur [XZ] et (PQ) ∥ (YZ). Quelle égalité de Thalès faut-il écrire ?","expected":"XP/XY = XQ/XZ = PQ/YZ","alternatives":["XP/XZ = XQ/XY = PQ/YZ","XY/XP = XQ/XZ = YZ/PQ","XP/XY = XZ/XQ = PQ/YZ"],"explanation":"Les correspondances sont XP↔XY, XQ↔XZ et PQ↔YZ ; les trois fractions sont dans le même sens.","feedback":["XP est sur XY, pas sur XZ : tu as interverti les côtés des deux directions.","Le premier et le dernier rapports sont inversés, mais pas le rapport du milieu.","XZ/XQ est grand/petit, contrairement aux deux autres rapports écrits petit/grand."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[1],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q04","prompt":"Dans une configuration papillon, A, O, C sont alignés dans cet ordre et B, O, D aussi ; (AB) ∥ (CD). Quels rapports sont égaux ?","expected":"OA/OC = OB/OD = AB/CD","alternatives":["OA/OD = OB/OC = AB/CD","OA/OC = OD/OB = AB/CD","OC/OA = OB/OD = CD/AB"],"explanation":"Même en configuration papillon, on compare les côtés correspondants issus du sommet commun O : OA/OC, OB/OD, AB/CD.","feedback":["OA et OD ne sont pas les côtés correspondants sur une même droite sécante.","OD/OB est l’inverse de OB/OD ; les autres fractions sont dans le sens petit/grand.","OC/OA et CD/AB sont inversés tandis que OB/OD ne l’est pas : les sens sont mélangés."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q05","prompt":"On sait AM/AB = AN/AC = MN/BC et AM = 4 cm, AB = 10 cm. Quelle valeur doit avoir le rapport MN/BC ?","expected":"2/5","alternatives":["5/2","2/3","4/5"],"explanation":"AM/AB = 4/10 = 2/5. Puisque les trois rapports sont égaux, MN/BC = 2/5.","feedback":["5/2 inverse le rapport 4/10 : on ne change pas le sens d’une seule fraction.","2/3 ne correspond pas à 4/10 : il faut simplifier par 2 pour obtenir 2/5.","4/5 vaut 0,8, tandis que AM/AB = 4/10 = 0,4 : ce n’est pas la même proportion."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q06","prompt":"Trois rapports sont annoncés : 4/10, 6/15 et 8/20. Sont-ils tous égaux ?","expected":"Oui : chacun vaut 2/5.","alternatives":["Non : 4/10 est différent de 6/15.","Non : 8/20 vaut 1/2.","Oui : chacun vaut 3/5."],"explanation":"4/10 = 2/5, 6/15 = 2/5 et 8/20 = 2/5 : les trois rapports sont égaux.","feedback":["6/15 se simplifie en 2/5, comme 4/10 : ces deux fractions sont égales.","8/20 vaut 0,4 = 2/5, et non un demi : il faut simplifier par 4.","3/5 vaut 0,6 ; ici les trois fractions valent 0,4, c’est-à-dire 2/5."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q07","prompt":"La vraie proportion est AM/AB = AN/AC = MN/BC. Quelle fraction faut-il corriger dans AB/AM = AN/AC = BC/MN ?","expected":"AN/AC doit devenir AC/AN.","alternatives":["AB/AM doit devenir AM/AB, uniquement.","BC/MN doit devenir MN/BC, uniquement.","Aucune : les fractions sont déjà cohérentes."],"explanation":"Les rapports AB/AM et BC/MN sont grand/petit. Il faut donc inverser AN/AC en AC/AN pour conserver la même orientation.","feedback":["Changer seulement AB/AM en AM/AB mélangerait encore des rapports petit/grand et grand/petit.","Changer seulement BC/MN en MN/BC laisse un mélange : le premier rapport reste inversé.","Le rapport central AN/AC est dans un sens différent des deux autres ; cette égalité est donc incorrecte."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q08","prompt":"Dans le triangle ABC, M est sur [AB], N sur [AC] et (MN) ∥ (BC). On connaît AM, AB et AN ; on cherche AC. Quels deux rapports faut-il utiliser ?","expected":"AM/AB = AN/AC","alternatives":["AM/AB = MN/BC","AM/AN = AC/AB","AN/MN = BC/AC"],"explanation":"Les quatre données utiles pour AC sont AM, AB, AN et AC : il faut comparer AM/AB à AN/AC.","feedback":["MN et BC ne sont pas donnés : ce rapport ne permet pas de calculer directement AC avec les données annoncées.","AM/AN = AC/AB inverse les correspondances entre les deux directions : pour Thalès, AM/AN serait égal à AB/AC, pas à AC/AB.","AN/MN = BC/AC inverse le rapport des côtés homologues : la proportion correcte entre ces deux directions serait AN/MN = AC/BC."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q09","prompt":"M est sur [AB] et N sur [AC] ; AM = 3 cm, AB = 9 cm, AN = 4 cm et AC = 12 cm. Que permet de conclure la réciproque de Thalès ?","expected":"(MN) est parallèle à (BC).","alternatives":["(MN) est perpendiculaire à (BC).","(MN) ne peut pas être parallèle à (BC).","Le triangle ABC est forcément rectangle."],"explanation":"Les alignements sont dans le même ordre et 3/9 = 4/12 = 1/3 : la réciproque de Thalès prouve (MN) ∥ (BC).","feedback":["L’égalité des rapports prouve un parallélisme, pas une perpendicularité, selon la réciproque de Thalès.","3/9 et 4/12 sont égaux ; la réciproque conduit au parallélisme, pas à son exclusion.","L’égalité des rapports n’impose aucun angle droit au triangle ABC."],"docId":"ENT-leconTheoremedeThalespdf","pages":[3],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"},{"questionId":"MT16-Q10","prompt":"Dans le triangle ABC, M est sur [AB], N sur [AC] ; AM = 3 cm, AB = 8 cm, AN = 4 cm et AC = 10 cm. Que démontre la contraposée de Thalès ?","expected":"(MN) et (BC).","alternatives":["(MN) et (BC) sont parallèles.","(AB) et (AC) sont parallèles.","Le triangle ABC est rectangle en A."],"explanation":"AM/AB = 3/8 = 0,375 et AN/AC = 4/10 = 0,4. Ces rapports diffèrent : par la contraposée, (MN) et (BC) ne sont pas parallèles.","feedback":["Les deux rapports calculés sont différents ; les droites (MN) et (BC) ne peuvent donc pas être parallèles.","Les droites (AB) et (AC) se croisent en A dans le triangle ABC ; la contraposée porte sur (MN) et (BC).","Les calculs des rapports ne permettent pas de déduire un angle droit en A ; ils déterminent seulement le non-parallélisme de (MN) et (BC)."],"docId":"ENT-leconTheoremedeThalespdf","pages":[3],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS16"}],"MT17":[{"questionId":"MT17-Q01","prompt":"Programme n°1 : choisir x, soustraire 9, multiplier le résultat par 2, puis ajouter le triple du nombre de départ. Quelle expression réduite obtient-on ?","expected":"5x − 18","alternatives":["5x − 9","2x − 27","5x + 18"],"explanation":"On écrit 2(x − 9) + 3x = 2x − 18 + 3x = 5x − 18.","feedback":["Le nombre −9 doit lui aussi être multiplié par 2 : la constante finale vaut −18, pas −9.","On ajoute 3x au double de (x−9) ; on ne soustrait pas 27 au coefficient 2x.","Le produit 2 × (−9) vaut −18 : la constante ne devient pas positive."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q02","prompt":"Programme n°2 : choisir x, multiplier par −3, ajouter le carré du nombre de départ, puis ajouter 2. Quelle expression obtient-on ?","expected":"x² − 3x + 2","alternatives":["x² + 3x + 2","−3x² + 2","x² − 3x − 2"],"explanation":"Multiplier x par −3 donne −3x ; ajouter le carré x² puis 2 donne x² − 3x + 2.","feedback":["Le facteur indiqué est −3 : le terme linéaire est −3x, pas +3x.","L’instruction « ajouter le carré » donne +x² séparément ; on ne multiplie pas x² par −3.","La dernière étape demande d’ajouter 2, et non de retirer 2."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q03","prompt":"Programme n°3 : choisir x, ajouter 5, multiplier le résultat par le nombre de départ, puis soustraire 8. Quelle expression réduite obtient-on ?","expected":"x² + 5x − 8","alternatives":["2x + 5 − 8","x² + 5 − 8","x² − 5x − 8"],"explanation":"Le résultat x + 5 est multiplié par x : x(x + 5) − 8 = x² + 5x − 8.","feedback":["Multiplier (x + 5) par x n’est pas simplement additionner des x : il faut distribuer x.","Le produit x × 5 donne 5x ; on ne peut pas transformer ce terme en constante 5.","Ajouter 5 puis multiplier par x crée le terme +5x, et non −5x."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q04","prompt":"Programme n°4 : choisir x, multiplier par 2, ajouter 3, multiplier le résultat par −4, puis ajouter 4. Que vaut l’expression réduite ?","expected":"−8x − 8","alternatives":["−8x − 12","−8x + 16","8x − 8"],"explanation":"On obtient d’abord 2x + 3, puis −4(2x + 3) + 4 = −8x − 12 + 4 = −8x − 8.","feedback":["Tu as oublié la dernière étape +4 : −12 + 4 vaut −8, pas −12.","La multiplication par −4 donne −12 pour la constante ; avec +4, elle devient −8.","Multiplier 2x par −4 donne −8x, pas +8x : le signe moins est essentiel."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q05","prompt":"Programme n°5 : choisir x, ajouter 7, multiplier le résultat par 3, puis ajouter le cube du nombre de départ. Quelle expression réduite obtient-on ?","expected":"x³ + 3x + 21","alternatives":["x³ + 3x + 7","x³ + 21x","3x³ + 21"],"explanation":"On a 3(x + 7) + x³ = 3x + 21 + x³, soit x³ + 3x + 21.","feedback":["Le 7 doit être multiplié par 3 : cela donne 21, et non 7.","3x et 21 ne peuvent pas être regroupés en 21x : 21 est une constante.","Le cube du nombre de départ est x³, pas 3x³, puisqu’on ajoute ensuite ce cube."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q06","prompt":"Programme n°6 : choisir x, ajouter 1, mettre le résultat au carré, puis soustraire le double du nombre de départ. Que devient l’expression après réduction ?","expected":"x² + 1","alternatives":["x² + 2x + 1","x² − 1","x² + 2"],"explanation":"On calcule (x + 1)² − 2x = x² + 2x + 1 − 2x = x² + 1.","feedback":["Le terme +2x créé par le carré doit être annulé par l’étape finale −2x.","(x + 1)² contient le terme +1 et non −1 ; vérifie le carré de la somme.","Le carré de x+1 ne donne pas x²+2 : il faut développer (x+1)(x+1)."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q07","prompt":"Sur une fiche, une question présente deux triangles avec points alignés et (MN) ∥ (BC), puis demande une longueur ; une autre demande de traduire « choisir un nombre, puis soustraire 9 ». Quel ordre de méthodes faut-il utiliser ?","expected":"Thalès pour la longueur ; une expression littérale pour le programme.","alternatives":["Pythagore dans les deux questions.","Thalès dans les deux questions.","Le développement seul dans les deux questions."],"explanation":"Les parallèles et les triangles permettent d’utiliser Thalès. Une suite d’instructions sur un nombre se traduit avec x, puis se réduit si besoin.","feedback":["Aucun angle droit n’est donné dans la première question ; Pythagore ne traduit pas le programme de calcul.","Thalès donne une relation géométrique entre longueurs, pas l’expression d’un programme de calcul.","Développer une expression peut servir au programme, mais pas directement au calcul géométrique sans les rapports de Thalès."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[1,3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q08","prompt":"Dans ABC, M est sur [AB], N sur [AC], (MN) ∥ (BC) et AM/AB = 3/8. Si BC = 24 cm, quelle est la longueur MN ?","expected":"9 cm","alternatives":["64 cm","8 cm","21 cm"],"explanation":"Par Thalès, MN/BC = AM/AB = 3/8 ; donc MN = 24 × 3/8 = 9 cm.","feedback":["64 cm inverse 3/8 et donne une longueur bien trop grande : MN est 3/8 de BC.","8 cm confond le dénominateur 8 avec la longueur à calculer ; il faut multiplier par BC.","21 cm ne correspond pas à 24 × 3/8, qui donne 9 cm."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[1],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q09","prompt":"Pour le programme « soustraire 9, multiplier par 2, ajouter 3 fois le départ », un élève écrit 2(x − 9) + 3x = 5x − 9. Quelle est son erreur ?","expected":"Il a oublié de multiplier −9 par 2.","alternatives":["Il a ajouté 3x alors qu’il fallait le soustraire.","Il aurait dû écrire 2x + 9.","Il faut remplacer x par 9 avant de développer."],"explanation":"Le produit 2(x − 9) vaut 2x − 18. Avec +3x, le résultat est 5x − 18 : le −9 devait être doublé.","feedback":["La consigne dit bien « ajouter trois fois le départ » : le terme +3x est correct.","L’étape initiale consiste à retirer 9, donc le signe du terme constant reste négatif après multiplication.","Le nombre de départ est une variable x ; l’énoncé ne demande pas de lui donner la valeur 9."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"},{"questionId":"MT17-Q10","prompt":"On sait que (MN) ∥ (BC), MN/BC = 2/5 et BC = 15 cm. Un programme distinct donne f(x) = 2(x + 3). Combien vaut f(MN) ?","expected":"18","alternatives":["6","12","30"],"explanation":"Thalès : MN = 15 × 2/5 = 6. Puis f(6) = 2(6 + 3) = 18.","feedback":["6 est la longueur MN calculée grâce à Thalès ; il faut encore l’utiliser dans le programme f(x).","12 correspondrait à 2 × 6 sans ajouter 3 dans la parenthèse.","30 ne respecte pas les deux étapes : la longueur recherchée est 6, puis f(6)=18."],"docId":"ENT-Fichedetravailsurlegalitedes3rappor","pages":[1,3],"title":"Fiche de travailsur l’égalité des 3 rapports et prog de calcul.pdf","lessonId":"MBIS17"}],"MT18":[{"questionId":"MT18-Q01","prompt":"Une échelle de 5 m est posée contre un mur vertical, son pied étant à 3 m du mur. À quelle hauteur arrive son sommet ?","expected":"4 m","alternatives":["8 m","2 m","√34 m"],"explanation":"Le sol et le mur sont perpendiculaires : hauteur² = 5² − 3² = 16 ; la hauteur est 4 m.","feedback":["La réponse « 8 m » est incorrecte : Tu as ajouté deux longueurs sans utiliser les carrés. Le sol et le mur sont perpendiculaires : hauteur² = 5² − 3² = 16 ; la hauteur est 4 m.","La réponse « 2 m » est incorrecte : La différence 5 − 3 n’est pas la hauteur de ce triangle rectangle. Le sol et le mur sont perpendiculaires : hauteur² = 5² − 3² = 16 ; la hauteur est 4 m.","La réponse « √34 m » est incorrecte : Tu as additionné les carrés ; l’hypoténuse est déjà connue. Le sol et le mur sont perpendiculaires : hauteur² = 5² − 3² = 16 ; la hauteur est 4 m."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q02","prompt":"Un terrain rectangulaire mesure 15 m sur 20 m. Quelle est la longueur de sa diagonale ?","expected":"25 m","alternatives":["35 m","5 m","√175 m"],"explanation":"La diagonale est l’hypoténuse : √(15² + 20²) = √625 = 25 m.","feedback":["La réponse « 35 m » est incorrecte : Il ne faut pas simplement additionner longueur et largeur. La diagonale est l’hypoténuse : √(15² + 20²) = √625 = 25 m.","La réponse « 5 m » est incorrecte : La différence des côtés n’est pas la diagonale. La diagonale est l’hypoténuse : √(15² + 20²) = √625 = 25 m.","La réponse « √175 m » est incorrecte : On doit ajouter les carrés 225 et 400, pas les soustraire. La diagonale est l’hypoténuse : √(15² + 20²) = √625 = 25 m."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q03","prompt":"Dans le problème du centre de loisirs du DNB, C, E, D sont alignés dans cet ordre ; C, F, G le sont aussi. CE = 30 m, ED = 10 m, DG = 24 m et (EF) ∥ (DG). Quelle est la clôture EF ?","expected":"18 m","alternatives":["24 m","32 m","8 m"],"explanation":"CD = 30 + 10 = 40 m ; par Thalès, EF/DG = CE/CD = 30/40, donc EF = 24 × 30/40 = 18 m.","feedback":["La réponse « 24 m » est incorrecte : 24 m correspond à DG, le grand segment, pas à EF. CD = 30 + 10 = 40 m ; par Thalès, EF/DG = CE/CD = 30/40, donc EF = 24 × 30/40 = 18 m.","La réponse « 32 m » est incorrecte : Tu as inversé la réduction 30/40 et agrandi le petit segment. CD = 30 + 10 = 40 m ; par Thalès, EF/DG = CE/CD = 30/40, donc EF = 24 × 30/40 = 18 m.","La réponse « 8 m » est incorrecte : Tu as soustrait des longueurs sans appliquer les rapports. CD = 30 + 10 = 40 m ; par Thalès, EF/DG = CE/CD = 30/40, donc EF = 24 × 30/40 = 18 m."],"docId":"ENT-2026ExercicesThalesetPythagoreextra","pages":[2],"title":"2026 Exercices Thales et Pythagore extraits DNB.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q04","prompt":"Dans le problème du centre de loisirs, CD = 40 m et DG = 24 m, avec (CD) perpendiculaire à (DG). Quelle est la longueur CG arrondie au dixième ?","expected":"46,6 m","alternatives":["64 m","16 m","46,7 m"],"explanation":"CG² = 40² + 24² = 2176, d’où CG = √2176 ≈ 46,6476 m, soit 46,6 m au dixième.","feedback":["La réponse « 64 m » est incorrecte : Il faut calculer une racine carrée, pas additionner les côtés. CG² = 40² + 24² = 2176, d’où CG = √2176 ≈ 46,6476 m, soit 46,6 m au dixième.","La réponse « 16 m » est incorrecte : Il ne suffit pas de soustraire 40 et 24. CG² = 40² + 24² = 2176, d’où CG = √2176 ≈ 46,6476 m, soit 46,6 m au dixième.","La réponse « 46,7 m » est incorrecte : 46,6476 s’arrondit à 46,6 au dixième, car le chiffre des centièmes est 4. CG² = 40² + 24² = 2176, d’où CG = √2176 ≈ 46,6476 m, soit 46,6 m au dixième."],"docId":"ENT-2026ExercicesThalesetPythagoreextra","pages":[2],"title":"2026 Exercices Thales et Pythagore extraits DNB.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q05","prompt":"Une voile triangulaire a une base de 9 m et une hauteur perpendiculaire à cette base de 6 m. Quelle est son aire ?","expected":"27 m²","alternatives":["54 m²","15 m²","30 m²"],"explanation":"Aire = base × hauteur ÷ 2 = 9 × 6 ÷ 2 = 27 m².","feedback":["La réponse « 54 m² » est incorrecte : Tu as oublié de diviser le produit par deux. Aire = base × hauteur ÷ 2 = 9 × 6 ÷ 2 = 27 m².","La réponse « 15 m² » est incorrecte : Additionner les longueurs ne donne pas une aire. Aire = base × hauteur ÷ 2 = 9 × 6 ÷ 2 = 27 m².","La réponse « 30 m² » est incorrecte : Une aire s’obtient en multipliant base et hauteur puis en divisant par deux. Aire = base × hauteur ÷ 2 = 9 × 6 ÷ 2 = 27 m²."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[4],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q06","prompt":"Dans le problème du centre, la zone de jeux est un triangle de base 30 m et de hauteur 18 m. Un sac couvre 140 m² et coûte 22,90 €. Quel budget prévoir ?","expected":"45,80 €","alternatives":["22,90 €","68,70 €","540 €"],"explanation":"La surface vaut 30 × 18/2 = 270 m² ; il faut ⌈270/140⌉ = 2 sacs, soit 2 × 22,90 € = 45,80 €.","feedback":["La réponse « 22,90 € » est incorrecte : Un sac ne couvre que 140 m², moins que les 270 m² à semer. La surface vaut 30 × 18/2 = 270 m² ; il faut ⌈270/140⌉ = 2 sacs, soit 2 × 22,90 € = 45,80 €.","La réponse « 68,70 € » est incorrecte : Trois sacs seraient inutiles : deux suffisent à couvrir 270 m². La surface vaut 30 × 18/2 = 270 m² ; il faut ⌈270/140⌉ = 2 sacs, soit 2 × 22,90 € = 45,80 €.","La réponse « 540 € » est incorrecte : 540 correspond au produit 30 × 18 et n’est pas un prix. La surface vaut 30 × 18/2 = 270 m² ; il faut ⌈270/140⌉ = 2 sacs, soit 2 × 22,90 € = 45,80 €."],"docId":"ENT-2026ExercicesThalesetPythagoreextra","pages":[2],"title":"2026 Exercices Thales et Pythagore extraits DNB.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q07","prompt":"Le grand triangle du centre de loisirs a pour base 40 m et hauteur 24 m ; la zone de jeux a pour base 30 m et hauteur 18 m. Quelle est l’aire du potager (différence) ?","expected":"210 m²","alternatives":["480 m²","270 m²","750 m²"],"explanation":"Grand triangle : 40 × 24/2 = 480 m². Zone de jeux : 30 × 18/2 = 270 m². Différence : 210 m².","feedback":["La réponse « 480 m² » est incorrecte : 480 m² est la superficie du grand triangle, pas celle du potager seul. Grand triangle : 40 × 24/2 = 480 m². Zone de jeux : 30 × 18/2 = 270 m². Différence : 210 m².","La réponse « 270 m² » est incorrecte : 270 m² est la zone de jeux, pas le potager. Grand triangle : 40 × 24/2 = 480 m². Zone de jeux : 30 × 18/2 = 270 m². Différence : 210 m².","La réponse « 750 m² » est incorrecte : Il ne faut pas additionner les aires : le potager est la partie restante. Grand triangle : 40 × 24/2 = 480 m². Zone de jeux : 30 × 18/2 = 270 m². Différence : 210 m²."],"docId":"ENT-2026ExercicesThalesetPythagoreextra","pages":[2],"title":"2026 Exercices Thales et Pythagore extraits DNB.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q08","prompt":"Dans un triangle AMN rectangle en M, AM = 6 m et AN = 7,5 m. Dans un triangle ABC, avec M sur [AB], N sur [AC], (MN) ∥ (BC) et AB = 9 m, combien mesure BC ?","expected":"6,75 m","alternatives":["4,5 m","9,0 m","13,5 m"],"explanation":"Pythagore donne MN = √(7,5² − 6²) = 4,5 m, puis Thalès donne BC = 4,5 × 9/6 = 6,75 m.","feedback":["La réponse « 4,5 m » est incorrecte : 4,5 m est la longueur MN, avant l’agrandissement demandé. Pythagore donne MN = √(7,5² − 6²) = 4,5 m, puis Thalès donne BC = 4,5 × 9/6 = 6,75 m.","La réponse « 9,0 m » est incorrecte : AB n’est pas nécessairement égal à BC : il faut calculer un rapport. Pythagore donne MN = √(7,5² − 6²) = 4,5 m, puis Thalès donne BC = 4,5 × 9/6 = 6,75 m.","La réponse « 13,5 m » est incorrecte : 13,5 m vient d’un coefficient incorrect, le rapport AB/AM valant 1,5. Pythagore donne MN = √(7,5² − 6²) = 4,5 m, puis Thalès donne BC = 4,5 × 9/6 = 6,75 m."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[4],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q09","prompt":"Un triangle de côtés 9 cm, 12 cm et 15 cm est-il rectangle ?","expected":"Oui, par la réciproque de Pythagore.","alternatives":["Non, car 9 + 12 ≠ 15.","Oui, parce que 15 est la plus grande longueur.","Impossible sans dessin à l’échelle."],"explanation":"On compare les carrés : 9² + 12² = 81 + 144 = 225 = 15², donc le triangle est rectangle.","feedback":["La réponse « Non, car 9 + 12 ≠ 15. » est incorrecte : Comparer les longueurs directement ne remplace pas les carrés. On compare les carrés : 9² + 12² = 81 + 144 = 225 = 15², donc le triangle est rectangle.","La réponse « Oui, parce que 15 est la plus grande longueur. » est incorrecte : Le plus long côté n’est pas à lui seul une preuve d’angle droit. On compare les carrés : 9² + 12² = 81 + 144 = 225 = 15², donc le triangle est rectangle.","La réponse « Impossible sans dessin à l’échelle. » est incorrecte : Les mesures des trois côtés suffisent pour conclure. On compare les carrés : 9² + 12² = 81 + 144 = 225 = 15², donc le triangle est rectangle."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS18"},{"questionId":"MT18-Q10","prompt":"Dans un exercice du brevet, tu as calculé 12 cm en utilisant Pythagore. Quelle rédaction permet de justifier correctement le résultat ?","expected":"Indiquer le triangle rectangle, écrire l’égalité des carrés, calculer puis conclure avec l’unité.","alternatives":["Écrire uniquement « 12 cm ».","Mesurer 12 cm sur le dessin et écrire que c’est exact.","Écrire « Pythagore » sans montrer les calculs."],"explanation":"Au brevet, on précise pourquoi le triangle est rectangle, on applique la formule aux bons côtés, puis on conclut avec le résultat et l’unité.","feedback":["La réponse « Écrire uniquement « 12 cm ». » est incorrecte : Un résultat isolé ne montre ni le raisonnement ni les conditions d’application. Au brevet, on précise pourquoi le triangle est rectangle, on applique la formule aux bons côtés, puis on conclut avec le résultat et l’unité.","La réponse « Mesurer 12 cm sur le dessin et écrire que c’est exact. » est incorrecte : Un dessin n’est pas nécessairement à l’échelle, la mesure à la règle ne suffit pas. Au brevet, on précise pourquoi le triangle est rectangle, on applique la formule aux bons côtés, puis on conclut avec le résultat et l’unité.","La réponse « Écrire « Pythagore » sans montrer les calculs. » est incorrecte : Nommer le théorème ne justifie pas les opérations ni la conclusion. Au brevet, on précise pourquoi le triangle est rectangle, on applique la formule aux bons côtés, puis on conclut avec le résultat et l’unité."],"docId":"ENT-2026ExercicesThalesetPythagoreextra","pages":[1],"title":"2026 Exercices Thales et Pythagore extraits DNB.pdf","lessonId":"MBIS18"}],"MT19":[{"questionId":"MT19-Q01","prompt":"Calcule −8 + 13 − 4. Quel est le résultat ?","expected":"1","alternatives":["−1","9","−25"],"explanation":"−8 + 13 = 5 puis 5 − 4 = 1.","feedback":["La réponse « −1 » est incorrecte : Tu as changé le signe du résultat final. −8 + 13 = 5 puis 5 − 4 = 1.","La réponse « 9 » est incorrecte : Tu n’as pas soustrait les quatre dernières unités. −8 + 13 = 5 puis 5 − 4 = 1.","La réponse « −25 » est incorrecte : Tu as additionné les valeurs absolues comme si tout était négatif. −8 + 13 = 5 puis 5 − 4 = 1."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[1],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS19"},{"questionId":"MT19-Q02","prompt":"Calcule (−3)² − 2 × 4. Quel est le résultat ?","expected":"1","alternatives":["−17","28","−1"],"explanation":"On calcule d’abord la puissance et la multiplication : 9 − 8 = 1.","feedback":["La réponse « −17 » est incorrecte : (−3)² vaut +9 et non −9. On calcule d’abord la puissance et la multiplication : 9 − 8 = 1.","La réponse « 28 » est incorrecte : On ne peut pas multiplier toute l’expression par 4. On calcule d’abord la puissance et la multiplication : 9 − 8 = 1.","La réponse « −1 » est incorrecte : La différence 9 − 8 est positive, égale à 1. On calcule d’abord la puissance et la multiplication : 9 − 8 = 1."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[1],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS19"},{"questionId":"MT19-Q03","prompt":"Calcule 5/6 − 1/3. Quel résultat simplifié obtiens-tu ?","expected":"1/2","alternatives":["4/3","2/6","4/6"],"explanation":"On met au même dénominateur : 5/6 − 2/6 = 3/6 = 1/2.","feedback":["La réponse « 4/3 » est incorrecte : On ne soustrait pas les dénominateurs. On met au même dénominateur : 5/6 − 2/6 = 3/6 = 1/2.","La réponse « 2/6 » est incorrecte : 2/6 n’est pas égal à 3/6, il manque une part. On met au même dénominateur : 5/6 − 2/6 = 3/6 = 1/2.","La réponse « 4/6 » est incorrecte : 4/6 correspond à 5/6 − 1/6, mais 1/3 vaut 2/6. On met au même dénominateur : 5/6 − 2/6 = 3/6 = 1/2."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[3],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS19"},{"questionId":"MT19-Q04","prompt":"Un groupe compte 24 élèves. Les 3/8 participent à une activité. Combien cela fait-il d’élèves ?","expected":"9","alternatives":["8","3","16"],"explanation":"24 × 3/8 = 24 ÷ 8 × 3 = 9 élèves.","feedback":["La réponse « 8 » est incorrecte : 8 est le dénominateur de la fraction, pas le nombre recherché. 24 × 3/8 = 24 ÷ 8 × 3 = 9 élèves.","La réponse « 3 » est incorrecte : 3 correspond au numérateur, il faut aussi appliquer la fraction aux 24 élèves. 24 × 3/8 = 24 ÷ 8 × 3 = 9 élèves.","La réponse « 16 » est incorrecte : 16 ne correspond pas à trois huitièmes de 24. 24 × 3/8 = 24 ÷ 8 × 3 = 9 élèves."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[4],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS19"},{"questionId":"MT19-Q05","prompt":"Calcule 2³ × 2² sous la forme d’une seule puissance.","expected":"2⁵","alternatives":["2⁶","4⁵","2¹"],"explanation":"Deux puissances de même base se multiplient en additionnant les exposants : 2³ × 2² = 2⁵.","feedback":["La réponse « 2⁶ » est incorrecte : On ne multiplie pas les exposants quand les bases sont identiques. Deux puissances de même base se multiplient en additionnant les exposants : 2³ × 2² = 2⁵.","La réponse « 4⁵ » est incorrecte : Le produit des bases n’est pas la règle des puissances de même base. Deux puissances de même base se multiplient en additionnant les exposants : 2³ × 2² = 2⁵.","La réponse « 2¹ » est incorrecte : 3 + 2 vaut 5, pas 1. Deux puissances de même base se multiplient en additionnant les exposants : 2³ × 2² = 2⁵."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[5],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS19"},{"questionId":"MT19-Q06","prompt":"Quelle est l’écriture scientifique correcte de 0,00045 ?","expected":"4,5 × 10⁻⁴","alternatives":["45 × 10⁻⁵","4,5 × 10⁴","0,45 × 10⁻³"],"explanation":"La mantisse doit être entre 1 et 10 : 0,00045 = 4,5 × 10⁻⁴.","feedback":["La réponse « 45 × 10⁻⁵ » est incorrecte : 45 est supérieur à 10 ; ce produit a la bonne valeur mais n’est pas normalisé. La mantisse doit être entre 1 et 10 : 0,00045 = 4,5 × 10⁻⁴.","La réponse « 4,5 × 10⁴ » est incorrecte : Un exposant positif donnerait un nombre très grand. La mantisse doit être entre 1 et 10 : 0,00045 = 4,5 × 10⁻⁴.","La réponse « 0,45 × 10⁻³ » est incorrecte : 0,45 est inférieur à 1 : cette écriture n’est pas scientifique normalisée. La mantisse doit être entre 1 et 10 : 0,00045 = 4,5 × 10⁻⁴."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS19"},{"questionId":"MT19-Q07","prompt":"Parmi ces quatre nombres, lequel est divisible à la fois par 3 et par 5 ?","expected":"135","alternatives":["125","142","133"],"explanation":"135 se termine par 5 et 1 + 3 + 5 = 9, multiple de 3.","feedback":["La réponse « 125 » est incorrecte : 125 est divisible par 5 mais sa somme de chiffres vaut 8, non multiple de 3. 135 se termine par 5 et 1 + 3 + 5 = 9, multiple de 3.","La réponse « 142 » est incorrecte : 142 n’est ni terminé par 0 ou 5 ni de somme de chiffres multiple de 3. 135 se termine par 5 et 1 + 3 + 5 = 9, multiple de 3.","La réponse « 133 » est incorrecte : 133 a une somme de chiffres égale à 7 et ne se termine pas par 0 ou 5. 135 se termine par 5 et 1 + 3 + 5 = 9, multiple de 3."],"docId":"ENT-automatismes3emeseance51odp52odp","pages":[1],"title":"automatismes 3eme seance 5.1.odp / 5.2.odp","lessonId":"MBIS19"},{"questionId":"MT19-Q08","prompt":"Une séance commence à 9 h 45 et dure 1 h 35. À quelle heure se termine-t-elle ?","expected":"11 h 20","alternatives":["10 h 80","11 h 10","10 h 20"],"explanation":"9 h 45 + 1 h = 10 h 45 ; puis 35 min conduisent à 11 h 20.","feedback":["La réponse « 10 h 80 » est incorrecte : Une heure contient 60 minutes : 10 h 80 doit être converti en 11 h 20. 9 h 45 + 1 h = 10 h 45 ; puis 35 min conduisent à 11 h 20.","La réponse « 11 h 10 » est incorrecte : Tu as ajouté 25 minutes au lieu de 35. 9 h 45 + 1 h = 10 h 45 ; puis 35 min conduisent à 11 h 20.","La réponse « 10 h 20 » est incorrecte : Tu as oublié le passage à l’heure suivante en ajoutant 35 minutes. 9 h 45 + 1 h = 10 h 45 ; puis 35 min conduisent à 11 h 20."],"docId":"ENT-automatismes3emeseance51odp52odp","pages":[1],"title":"automatismes 3eme seance 5.1.odp / 5.2.odp","lessonId":"MBIS19"},{"questionId":"MT19-Q09","prompt":"Convertis 2 h 15 min en minutes. Quel résultat obtiens-tu ?","expected":"135 min","alternatives":["215 min","125 min","120 min"],"explanation":"2 h = 120 min ; en ajoutant 15 min, on obtient 135 min.","feedback":["La réponse « 215 min » est incorrecte : Il ne faut pas juxtaposer les chiffres 2 et 15. 2 h = 120 min ; en ajoutant 15 min, on obtient 135 min.","La réponse « 125 min » est incorrecte : Deux heures représentent 120 minutes, pas 110. 2 h = 120 min ; en ajoutant 15 min, on obtient 135 min.","La réponse « 120 min » est incorrecte : Les 15 minutes supplémentaires ont été oubliées. 2 h = 120 min ; en ajoutant 15 min, on obtient 135 min."],"docId":"ENT-automatismes3emeseance51odp52odp","pages":[1],"title":"automatismes 3eme seance 5.1.odp / 5.2.odp","lessonId":"MBIS19"},{"questionId":"MT19-Q10","prompt":"Calcule 10⁻³. Quelle écriture décimale correspond ?","expected":"0,001","alternatives":["−1000","0,01","1000"],"explanation":"10⁻³ = 1/10³ = 1/1000 = 0,001.","feedback":["La réponse « −1000 » est incorrecte : L’exposant négatif ne signifie pas que la valeur est négative. 10⁻³ = 1/10³ = 1/1000 = 0,001.","La réponse « 0,01 » est incorrecte : 0,01 correspond à 10⁻², pas 10⁻³. 10⁻³ = 1/10³ = 1/1000 = 0,001.","La réponse « 1000 » est incorrecte : 1000 correspond à 10³, un exposant positif. 10⁻³ = 1/10³ = 1/1000 = 0,001."],"docId":"ENT-Calculsnumeriqueslecon2026pdf","pages":[6],"title":"Calculs numériques leçon 2026.pdf","lessonId":"MBIS19"}],"MT20":[{"questionId":"MT20-Q01","prompt":"Réduis 7x − 3x + 2. Quel résultat obtiens-tu ?","expected":"4x + 2","alternatives":["4x","10x + 2","4x − 2"],"explanation":"Les coefficients des termes en x se soustraient : 7x − 3x = 4x, puis on garde +2.","feedback":["La réponse « 4x » est incorrecte : Tu as supprimé le nombre constant +2. Les coefficients des termes en x se soustraient : 7x − 3x = 4x, puis on garde +2.","La réponse « 10x + 2 » est incorrecte : Tu as additionné les coefficients au lieu de faire 7 − 3. Les coefficients des termes en x se soustraient : 7x − 3x = 4x, puis on garde +2.","La réponse « 4x − 2 » est incorrecte : Le terme constant est positif dans l’énoncé. Les coefficients des termes en x se soustraient : 7x − 3x = 4x, puis on garde +2."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q02","prompt":"Réduis 3x² + 5x − 2x². Quelle expression reste ?","expected":"x² + 5x","alternatives":["6x","x² + 3x","x² + 5"],"explanation":"3x² − 2x² = x², tandis que 5x reste un terme différent.","feedback":["La réponse « 6x » est incorrecte : Les termes en x et x² ne se regroupent pas en 6x. 3x² − 2x² = x², tandis que 5x reste un terme différent.","La réponse « x² + 3x » est incorrecte : Tu as modifié le coefficient du terme en x, qui reste 5. 3x² − 2x² = x², tandis que 5x reste un terme différent.","La réponse « x² + 5 » est incorrecte : Le terme 5x n’est pas une constante sans x. 3x² − 2x² = x², tandis que 5x reste un terme différent."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q03","prompt":"Développe 4(2x + 3). Quelle expression réduite obtiens-tu ?","expected":"8x + 12","alternatives":["8x + 3","6x + 12","8x + 7"],"explanation":"On multiplie les deux termes de la parenthèse : 4 × 2x = 8x et 4 × 3 = 12.","feedback":["La réponse « 8x + 3 » est incorrecte : Tu as oublié de distribuer 4 au terme constant 3. On multiplie les deux termes de la parenthèse : 4 × 2x = 8x et 4 × 3 = 12.","La réponse « 6x + 12 » est incorrecte : On multiplie les coefficients 4 × 2, on ne les additionne pas. On multiplie les deux termes de la parenthèse : 4 × 2x = 8x et 4 × 3 = 12.","La réponse « 8x + 7 » est incorrecte : 4 × 3 vaut 12, pas 7. On multiplie les deux termes de la parenthèse : 4 × 2x = 8x et 4 × 3 = 12."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q04","prompt":"Développe −3(x − 4). Quel est le résultat ?","expected":"−3x + 12","alternatives":["−3x − 12","3x + 12","−3x + 4"],"explanation":"−3 × x = −3x et (−3) × (−4) = +12.","feedback":["La réponse « −3x − 12 » est incorrecte : Le produit de deux nombres négatifs est positif, d’où +12. −3 × x = −3x et (−3) × (−4) = +12.","La réponse « 3x + 12 » est incorrecte : Le coefficient de x doit rester négatif. −3 × x = −3x et (−3) × (−4) = +12.","La réponse « −3x + 4 » est incorrecte : Tu n’as pas multiplié −4 par −3. −3 × x = −3x et (−3) × (−4) = +12."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q05","prompt":"Réduis 8x − (5x + 7). Quel résultat obtiens-tu ?","expected":"3x − 7","alternatives":["3x + 7","13x − 7","8x − 5x + 7"],"explanation":"Le signe moins change les deux signes : 8x − 5x − 7 = 3x − 7.","feedback":["La réponse « 3x + 7 » est incorrecte : Le +7 devient −7 quand on supprime les parenthèses précédées de moins. Le signe moins change les deux signes : 8x − 5x − 7 = 3x − 7.","La réponse « 13x − 7 » est incorrecte : On soustrait 5x, on ne l’ajoute pas à 8x. Le signe moins change les deux signes : 8x − 5x − 7 = 3x − 7.","La réponse « 8x − 5x + 7 » est incorrecte : Tu as oublié de changer le signe du 7 dans la parenthèse. Le signe moins change les deux signes : 8x − 5x − 7 = 3x − 7."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q06","prompt":"Développe (x + 2)(x + 3). Quelle expression réduite obtiens-tu ?","expected":"x² + 5x + 6","alternatives":["x² + 6","x² + 5x","x² + 6x + 5"],"explanation":"Les quatre produits sont x², 3x, 2x et 6 : d’où x² + 5x + 6.","feedback":["La réponse « x² + 6 » est incorrecte : Tu as oublié les deux produits croisés en x. Les quatre produits sont x², 3x, 2x et 6 : d’où x² + 5x + 6.","La réponse « x² + 5x » est incorrecte : Tu as oublié le produit constant 2 × 3 = 6. Les quatre produits sont x², 3x, 2x et 6 : d’où x² + 5x + 6.","La réponse « x² + 6x + 5 » est incorrecte : Tu as échangé la somme des coefficients 2 + 3 et leur produit 2 × 3. Les quatre produits sont x², 3x, 2x et 6 : d’où x² + 5x + 6."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q07","prompt":"Développe (x − 2)(x + 5). Quelle expression réduite obtiens-tu ?","expected":"x² + 3x − 10","alternatives":["x² + 7x − 10","x² + 3x + 10","x² − 10"],"explanation":"Les quatre produits donnent x² + 5x − 2x − 10, donc x² + 3x − 10.","feedback":["La réponse « x² + 7x − 10 » est incorrecte : Les termes en x se réduisent à 5x − 2x = 3x. Les quatre produits donnent x² + 5x − 2x − 10, donc x² + 3x − 10.","La réponse « x² + 3x + 10 » est incorrecte : Le produit −2 × 5 est −10, pas +10. Les quatre produits donnent x² + 5x − 2x − 10, donc x² + 3x − 10.","La réponse « x² − 10 » est incorrecte : Tu as oublié les produits croisés 5x et −2x. Les quatre produits donnent x² + 5x − 2x − 10, donc x² + 3x − 10."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q08","prompt":"Calcule 3x² − 2 pour x = −2. Quel nombre obtiens-tu ?","expected":"10","alternatives":["−14","34","−10"],"explanation":"On remplace x par (−2) : 3 × (−2)² − 2 = 3 × 4 − 2 = 10.","feedback":["La réponse « −14 » est incorrecte : Le carré de −2 est +4, pas −4. On remplace x par (−2) : 3 × (−2)² − 2 = 3 × 4 − 2 = 10.","La réponse « 34 » est incorrecte : Tu as effectué une opération inutile : 3 × 4 vaut 12, puis on retire 2. On remplace x par (−2) : 3 × (−2)² − 2 = 3 × 4 − 2 = 10.","La réponse « −10 » est incorrecte : Le résultat est positif car 12 − 2 = 10. On remplace x par (−2) : 3 × (−2)² − 2 = 3 × 4 − 2 = 10."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q09","prompt":"Réduis −5a + 2a − 4. Quel résultat obtiens-tu ?","expected":"−3a − 4","alternatives":["3a − 4","−7a − 4","−3a + 4"],"explanation":"−5a + 2a = −3a, puis le nombre constant −4 reste.","feedback":["La réponse « 3a − 4 » est incorrecte : Le coefficient −3 est négatif, car −5 + 2 = −3. −5a + 2a = −3a, puis le nombre constant −4 reste.","La réponse « −7a − 4 » est incorrecte : −5 + 2 n’est pas égal à −7. −5a + 2a = −3a, puis le nombre constant −4 reste.","La réponse « −3a + 4 » est incorrecte : Le terme constant est −4, pas +4. −5a + 2a = −3a, puis le nombre constant −4 reste."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[1],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"},{"questionId":"MT20-Q10","prompt":"Choisis un nombre x, ajoute 4, puis multiplie le résultat par 3. Quelle expression représente le calcul ?","expected":"3(x + 4)","alternatives":["3x + 4","x + 12","3x − 12"],"explanation":"La multiplication porte sur le résultat entier x + 4, d’où 3(x + 4) = 3x + 12.","feedback":["La réponse « 3x + 4 » est incorrecte : Il manque la multiplication du 4 par 3. La multiplication porte sur le résultat entier x + 4, d’où 3(x + 4) = 3x + 12.","La réponse « x + 12 » est incorrecte : Il manque la multiplication du x par 3. La multiplication porte sur le résultat entier x + 4, d’où 3(x + 4) = 3x + 12.","La réponse « 3x − 12 » est incorrecte : Le programme demande d’ajouter 4, pas de soustraire 4. La multiplication porte sur le résultat entier x + 4, d’où 3(x + 4) = 3x + 12."],"docId":"ENT-leconcalcullitteralpartie1Developpe","pages":[2],"title":"leçon calcul littéral partie1 Developper.pdf","lessonId":"MBIS20"}],"MT21":[{"questionId":"MT21-Q01","prompt":"Un triangle est déclaré rectangle en B ; on connaît AB et BC, et on cherche AC. Quel théorème utiliser ?","expected":"Le théorème de Pythagore.","alternatives":["La réciproque de Pythagore.","Le théorème de Thalès.","La formule de l’aire uniquement."],"explanation":"L’angle droit est déjà connu et l’on cherche une longueur : on utilise directement AC² = AB² + BC².","feedback":["La réponse « La réciproque de Pythagore. » est incorrecte : La réciproque sert à établir l’angle droit, déjà donné ici. L’angle droit est déjà connu et l’on cherche une longueur : on utilise directement AC² = AB² + BC².","La réponse « Le théorème de Thalès. » est incorrecte : Thalès exige des segments parallèles, absents de la situation. L’angle droit est déjà connu et l’on cherche une longueur : on utilise directement AC² = AB² + BC².","La réponse « La formule de l’aire uniquement. » est incorrecte : L’aire seule n’établit pas l’égalité des carrés des côtés. L’angle droit est déjà connu et l’on cherche une longueur : on utilise directement AC² = AB² + BC²."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q02","prompt":"Un triangle possède des côtés de 5, 12 et 13 cm ; on veut prouver qu’il est rectangle. Quel outil convient ?","expected":"La réciproque de Pythagore.","alternatives":["La contraposée de Pythagore.","Le théorème de Thalès.","La somme 5 + 12 = 17."],"explanation":"5² + 12² = 25 + 144 = 169 = 13² ; l’égalité des carrés permet de prouver l’angle droit.","feedback":["La réponse « La contraposée de Pythagore. » est incorrecte : La contraposée s’utilise lorsque l’égalité des carrés n’est pas vérifiée. 5² + 12² = 25 + 144 = 169 = 13² ; l’égalité des carrés permet de prouver l’angle droit.","La réponse « Le théorème de Thalès. » est incorrecte : Aucun parallélisme n’est indiqué pour utiliser Thalès. 5² + 12² = 25 + 144 = 169 = 13² ; l’égalité des carrés permet de prouver l’angle droit.","La réponse « La somme 5 + 12 = 17. » est incorrecte : La somme des côtés ne prouve pas qu’un triangle est rectangle. 5² + 12² = 25 + 144 = 169 = 13² ; l’égalité des carrés permet de prouver l’angle droit."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q03","prompt":"Un triangle a des côtés de 4, 5 et 6 cm ; tu veux montrer qu’il n’est pas rectangle. Quelle propriété permet de conclure ?","expected":"La contraposée de Pythagore.","alternatives":["La réciproque qui conclut toujours rectangle.","Thalès appliqué à trois côtés seulement.","Le périmètre du triangle."],"explanation":"4² + 5² = 41, tandis que 6² = 36 ; l’inégalité montre, par contraposée, que le triangle n’est pas rectangle.","feedback":["La réponse « La réciproque qui conclut toujours rectangle. » est incorrecte : La réciproque ne permet de conclure rectangle que lorsque les carrés sont égaux. 4² + 5² = 41, tandis que 6² = 36 ; l’inégalité montre, par contraposée, que le triangle n’est pas rectangle.","La réponse « Thalès appliqué à trois côtés seulement. » est incorrecte : Thalès demande des alignements et des droites parallèles. 4² + 5² = 41, tandis que 6² = 36 ; l’inégalité montre, par contraposée, que le triangle n’est pas rectangle.","La réponse « Le périmètre du triangle. » est incorrecte : Le périmètre n’indique pas si un angle est droit. 4² + 5² = 41, tandis que 6² = 36 ; l’inégalité montre, par contraposée, que le triangle n’est pas rectangle."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q04","prompt":"Dans ABC, M appartient à [AB], N à [AC] et (MN) ∥ (BC). Quel théorème sert à calculer AC avec AM, AB et AN ?","expected":"Le théorème de Thalès.","alternatives":["La réciproque de Pythagore.","Le calcul de l’aire.","Le théorème de Pythagore."],"explanation":"Les alignements et les droites parallèles permettent d’écrire AM/AB = AN/AC et d’utiliser un produit en croix.","feedback":["La réponse « La réciproque de Pythagore. » est incorrecte : Aucun test d’angle droit n’est demandé. Les alignements et les droites parallèles permettent d’écrire AM/AB = AN/AC et d’utiliser un produit en croix.","La réponse « Le calcul de l’aire. » est incorrecte : Une aire ne fournit pas ici les rapports entre les longueurs. Les alignements et les droites parallèles permettent d’écrire AM/AB = AN/AC et d’utiliser un produit en croix.","La réponse « Le théorème de Pythagore. » est incorrecte : Aucun angle droit n’est précisé ; l’outil pertinent est la proportionnalité. Les alignements et les droites parallèles permettent d’écrire AM/AB = AN/AC et d’utiliser un produit en croix."],"docId":"ENT-leconTheoremedeThalespdf","pages":[2],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q05","prompt":"A, M, B sont alignés dans le même ordre que A, N, C ; on connaît AM/AB = AN/AC. Quel théorème peut établir (MN) ∥ (BC) ?","expected":"La réciproque de Thalès.","alternatives":["Thalès direct sans connaître les parallèles.","Pythagore direct.","La contraposée de Thalès."],"explanation":"Pour démontrer le parallélisme à partir de rapports égaux, avec les alignements nécessaires, on utilise la réciproque de Thalès.","feedback":["La réponse « Thalès direct sans connaître les parallèles. » est incorrecte : Le théorème direct suppose déjà les parallèles, alors qu’il faut les établir. Pour démontrer le parallélisme à partir de rapports égaux, avec les alignements nécessaires, on utilise la réciproque de Thalès.","La réponse « Pythagore direct. » est incorrecte : Aucun angle droit n’est donné pour Pythagore. Pour démontrer le parallélisme à partir de rapports égaux, avec les alignements nécessaires, on utilise la réciproque de Thalès.","La réponse « La contraposée de Thalès. » est incorrecte : La contraposée est utilisée lorsque les rapports ne sont pas égaux. Pour démontrer le parallélisme à partir de rapports égaux, avec les alignements nécessaires, on utilise la réciproque de Thalès."],"docId":"ENT-leconTheoremedeThalespdf","pages":[3],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q06","prompt":"A, M, B sont alignés ; A, N, C sont alignés et AM/AB = 2/5 tandis que AN/AC = 3/5. Que permet de déduire la contraposée de Thalès ?","expected":"(MN) n’est pas parallèle à (BC).","alternatives":["(MN) est parallèle à (BC).","Le triangle ABC est rectangle.","Les triangles ont la même aire."],"explanation":"Si les droites étaient parallèles, les deux rapports seraient égaux. Or 2/5 ≠ 3/5 : les droites ne sont pas parallèles.","feedback":["La réponse « (MN) est parallèle à (BC). » est incorrecte : Des rapports inégaux sont incompatibles avec le parallélisme de la configuration. Si les droites étaient parallèles, les deux rapports seraient égaux. Or 2/5 ≠ 3/5 : les droites ne sont pas parallèles.","La réponse « Le triangle ABC est rectangle. » est incorrecte : Une comparaison de rapports ne démontre pas un angle droit. Si les droites étaient parallèles, les deux rapports seraient égaux. Or 2/5 ≠ 3/5 : les droites ne sont pas parallèles.","La réponse « Les triangles ont la même aire. » est incorrecte : La question porte sur des droites et non sur une égalité des aires. Si les droites étaient parallèles, les deux rapports seraient égaux. Or 2/5 ≠ 3/5 : les droites ne sont pas parallèles."],"docId":"ENT-leconTheoremedeThalespdf","pages":[3],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q07","prompt":"Dans deux triangles emboîtés avec des côtés correspondants parallèles, un angle droit est aussi marqué. Pour trouver une longueur à partir du rapport petit/grand, quel théorème choisir ?","expected":"Le théorème de Thalès.","alternatives":["Pythagore sans utiliser les parallèles.","La réciproque de Pythagore.","La contraposée de Pythagore."],"explanation":"Lorsqu’on connaît un rapport de deux triangles formés par des droites parallèles, Thalès relie directement les côtés correspondants.","feedback":["La réponse « Pythagore sans utiliser les parallèles. » est incorrecte : Pythagore peut être utile ailleurs, mais il n’exploite pas ici les longueurs correspondantes des deux triangles. Lorsqu’on connaît un rapport de deux triangles formés par des droites parallèles, Thalès relie directement les côtés correspondants.","La réponse « La réciproque de Pythagore. » est incorrecte : La réciproque sert à prouver un angle droit, déjà indiqué. Lorsqu’on connaît un rapport de deux triangles formés par des droites parallèles, Thalès relie directement les côtés correspondants.","La réponse « La contraposée de Pythagore. » est incorrecte : La contraposée sert à prouver qu’un angle n’est pas droit, contrairement aux données. Lorsqu’on connaît un rapport de deux triangles formés par des droites parallèles, Thalès relie directement les côtés correspondants."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q08","prompt":"Sur un croquis, deux segments ont l’air parallèles mais rien ne l’affirme. Peut-on utiliser Thalès directement ?","expected":"Non, il faut une donnée ou une preuve de parallélisme.","alternatives":["Oui, un dessin suffit.","Oui, si le grand triangle est plus large.","Oui, dès qu’il y a deux triangles."],"explanation":"L’apparence visuelle ne garantit pas un parallélisme ; il faut un fait établi avant d’écrire les rapports de Thalès.","feedback":["La réponse « Oui, un dessin suffit. » est incorrecte : Mesurer à l’œil n’est pas une démonstration. L’apparence visuelle ne garantit pas un parallélisme ; il faut un fait établi avant d’écrire les rapports de Thalès.","La réponse « Oui, si le grand triangle est plus large. » est incorrecte : La taille du triangle ne prouve pas le parallélisme. L’apparence visuelle ne garantit pas un parallélisme ; il faut un fait établi avant d’écrire les rapports de Thalès.","La réponse « Oui, dès qu’il y a deux triangles. » est incorrecte : La présence de deux triangles sans condition supplémentaire ne suffit pas. L’apparence visuelle ne garantit pas un parallélisme ; il faut un fait établi avant d’écrire les rapports de Thalès."],"docId":"ENT-leconTheoremedeThalespdf","pages":[1],"title":"leçon Théorème de Thalès.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q09","prompt":"Dans un triangle rectangle, les côtés de l’angle droit mesurent 6 et 8 cm. Après avoir calculé la longueur du troisième côté, quelle valeur et méthode donner ?","expected":"10 cm, avec Pythagore.","alternatives":["14 cm, en additionnant les côtés.","10 cm, avec Thalès sans parallèles.","2 cm, en soustrayant les côtés."],"explanation":"Pythagore direct : hypoténuse = √(6² + 8²) = √100 = 10 cm.","feedback":["La réponse « 14 cm, en additionnant les côtés. » est incorrecte : L’addition 6 + 8 ne donne pas la longueur de l’hypoténuse. Pythagore direct : hypoténuse = √(6² + 8²) = √100 = 10 cm.","La réponse « 10 cm, avec Thalès sans parallèles. » est incorrecte : La valeur 10 est correcte, mais Thalès n’est pas justifié sans parallèles. Pythagore direct : hypoténuse = √(6² + 8²) = √100 = 10 cm.","La réponse « 2 cm, en soustrayant les côtés. » est incorrecte : La différence 8 − 6 n’est pas la longueur de l’hypoténuse. Pythagore direct : hypoténuse = √(6² + 8²) = √100 = 10 cm."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[1],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS21"},{"questionId":"MT21-Q10","prompt":"Tu trouves 7² + 24² = 625 et 25² = 625 pour un triangle de côtés 7, 24 et 25 cm. Quelle conclusion est justifiée ?","expected":"Le triangle est rectangle par la réciproque de Pythagore.","alternatives":["Le triangle n’est pas rectangle.","Le triangle est rectangle par Thalès sans parallèles.","On ne peut rien conclure."],"explanation":"Les carrés des deux plus petits côtés ont pour somme le carré du plus grand : 49 + 576 = 625 ; la réciproque s’applique.","feedback":["La réponse « Le triangle n’est pas rectangle. » est incorrecte : L’égalité des carrés permet précisément de démontrer l’angle droit. Les carrés des deux plus petits côtés ont pour somme le carré du plus grand : 49 + 576 = 625 ; la réciproque s’applique.","La réponse « Le triangle est rectangle par Thalès sans parallèles. » est incorrecte : Il n’y a pas de parallélisme, la conclusion vient de Pythagore. Les carrés des deux plus petits côtés ont pour somme le carré du plus grand : 49 + 576 = 625 ; la réciproque s’applique.","La réponse « On ne peut rien conclure. » est incorrecte : Les trois longueurs suffisent : on peut conclure. Les carrés des deux plus petits côtés ont pour somme le carré du plus grand : 49 + 576 = 625 ; la réciproque s’applique."],"docId":"ENT-LeconPythagoreacompleterpdf","pages":[2],"title":"Leçon Pythagore à compléter.pdf","lessonId":"MBIS21"}],"MT22":[{"questionId":"MT22-Q01","prompt":"Calcule 5/6 − (11/4 × 4/9). Quel résultat irréductible obtiens-tu (sujet A corrigé) ?","expected":"−7/18","alternatives":["7/18","−7/9","−29/18"],"explanation":"On multiplie d’abord : 11/4 × 4/9 = 11/9, puis 5/6 − 11/9 = 15/18 − 22/18 = −7/18.","feedback":["La réponse « 7/18 » est incorrecte : Le deuxième terme est plus grand que le premier, donc le résultat est négatif. On multiplie d’abord : 11/4 × 4/9 = 11/9, puis 5/6 − 11/9 = 15/18 − 22/18 = −7/18.","La réponse « −7/9 » est incorrecte : Le dénominateur commun choisi doit respecter 5/6 et 11/9 : on trouve 18. On multiplie d’abord : 11/4 × 4/9 = 11/9, puis 5/6 − 11/9 = 15/18 − 22/18 = −7/18.","La réponse « −29/18 » est incorrecte : La soustraction des numérateurs donne 15 − 22 = −7, pas −29. On multiplie d’abord : 11/4 × 4/9 = 11/9, puis 5/6 − 11/9 = 15/18 − 22/18 = −7/18."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q02","prompt":"Calcule 5/6 − (13/4 × 4/9). Quel résultat irréductible obtiens-tu (sujet B corrigé) ?","expected":"−11/18","alternatives":["11/18","−11/9","−26/18"],"explanation":"On calcule 13/4 × 4/9 = 13/9, puis 5/6 − 13/9 = 15/18 − 26/18 = −11/18.","feedback":["La réponse « 11/18 » est incorrecte : 13/9 est supérieur à 5/6, donc le résultat est négatif. On calcule 13/4 × 4/9 = 13/9, puis 5/6 − 13/9 = 15/18 − 26/18 = −11/18.","La réponse « −11/9 » est incorrecte : Le dénominateur commun 18 est nécessaire pour comparer correctement ces fractions. On calcule 13/4 × 4/9 = 13/9, puis 5/6 − 13/9 = 15/18 − 26/18 = −11/18.","La réponse « −26/18 » est incorrecte : 15 − 26 vaut −11 ; on ne conserve pas seulement −26. On calcule 13/4 × 4/9 = 13/9, puis 5/6 − 13/9 = 15/18 − 26/18 = −11/18."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q03","prompt":"Pour le sujet A, réduis E = 5x − (2x + 9). Quel résultat obtiens-tu ?","expected":"3x − 9","alternatives":["3x + 9","7x − 9","3x"],"explanation":"Le signe moins change les deux termes de la parenthèse : E = 5x − 2x − 9 = 3x − 9.","feedback":["La réponse « 3x + 9 » est incorrecte : Le +9 devient −9, pas +9. Le signe moins change les deux termes de la parenthèse : E = 5x − 2x − 9 = 3x − 9.","La réponse « 7x − 9 » est incorrecte : Il faut soustraire 2x et non l’ajouter. Le signe moins change les deux termes de la parenthèse : E = 5x − 2x − 9 = 3x − 9.","La réponse « 3x » est incorrecte : Le terme constant −9 ne disparaît pas. Le signe moins change les deux termes de la parenthèse : E = 5x − 2x − 9 = 3x − 9."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q04","prompt":"Développe puis réduis H = (3x + 2)(4x + 5), comme dans le sujet A du contrôle.","expected":"12x² + 23x + 10","alternatives":["12x² + 15x + 10","12x² + 23x − 10","7x² + 23x + 10"],"explanation":"Les quatre produits donnent 12x² + 15x + 8x + 10 = 12x² + 23x + 10.","feedback":["La réponse « 12x² + 15x + 10 » est incorrecte : Tu as oublié le produit 2 × 4x = 8x. Les quatre produits donnent 12x² + 15x + 8x + 10 = 12x² + 23x + 10.","La réponse « 12x² + 23x − 10 » est incorrecte : 2 × 5 vaut +10, pas −10. Les quatre produits donnent 12x² + 15x + 8x + 10 = 12x² + 23x + 10.","La réponse « 7x² + 23x + 10 » est incorrecte : 3x × 4x donne 12x², pas 7x². Les quatre produits donnent 12x² + 15x + 8x + 10 = 12x² + 23x + 10."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q05","prompt":"Le programme A : choisir x, retirer 2, multiplier par 4, soustraire 3x, puis ajouter 8. Quelle expression réduite obtient-on ?","expected":"x","alternatives":["x − 8","4x","7x"],"explanation":"4(x − 2) − 3x + 8 = 4x − 8 − 3x + 8 = x : on retrouve toujours le nombre de départ.","feedback":["La réponse « x − 8 » est incorrecte : Le −8 du développement est compensé par le +8 final. 4(x − 2) − 3x + 8 = 4x − 8 − 3x + 8 = x : on retrouve toujours le nombre de départ.","La réponse « 4x » est incorrecte : Il faut encore soustraire 3x après avoir multiplié par 4. 4(x − 2) − 3x + 8 = 4x − 8 − 3x + 8 = x : on retrouve toujours le nombre de départ.","La réponse « 7x » est incorrecte : Soustraire 3x et non l’ajouter modifie complètement le coefficient. 4(x − 2) − 3x + 8 = 4x − 8 − 3x + 8 = x : on retrouve toujours le nombre de départ."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[2],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q06","prompt":"Le programme B : choisir x, retirer 4, multiplier par 3, soustraire 2x, puis ajouter 12. Quelle expression réduite obtient-on ?","expected":"x","alternatives":["x − 12","5x","3x + 12"],"explanation":"3(x − 4) − 2x + 12 = 3x − 12 − 2x + 12 = x : les constantes s’annulent.","feedback":["La réponse « x − 12 » est incorrecte : Le +12 compense le −12 issu du développement. 3(x − 4) − 2x + 12 = 3x − 12 − 2x + 12 = x : les constantes s’annulent.","La réponse « 5x » est incorrecte : Il faut soustraire 2x, ce qui donne 1x et non 5x. 3(x − 4) − 2x + 12 = 3x − 12 − 2x + 12 = x : les constantes s’annulent.","La réponse « 3x + 12 » est incorrecte : Le programme comporte aussi la soustraction de 2x et de 4 avant multiplication. 3(x − 4) − 2x + 12 = 3x − 12 − 2x + 12 = x : les constantes s’annulent."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[2],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q07","prompt":"Sujet A : G, H, I sont alignés et J, H, F sont alignés ; (GF) ∥ (JI). GH = 8 cm, HI = 5 cm, HF = 10 cm. Calcule HJ.","expected":"6,25 cm","alternatives":["16 cm","4 cm","12 cm"],"explanation":"Thalès : GH/HI = HF/HJ, soit 8/5 = 10/HJ. Donc HJ = 5 × 10/8 = 6,25 cm.","feedback":["La réponse « 16 cm » est incorrecte : 16 résulte d’un produit en croix dans le mauvais sens. Thalès : GH/HI = HF/HJ, soit 8/5 = 10/HJ. Donc HJ = 5 × 10/8 = 6,25 cm.","La réponse « 4 cm » est incorrecte : Il ne faut pas prendre une proportion arbitraire : HJ doit respecter 8/5 = 10/HJ. Thalès : GH/HI = HF/HJ, soit 8/5 = 10/HJ. Donc HJ = 5 × 10/8 = 6,25 cm.","La réponse « 12 cm » est incorrecte : 12 cm ne vérifie pas les rapports ; c’est une longueur qui peut concerner un autre segment. Thalès : GH/HI = HF/HJ, soit 8/5 = 10/HJ. Donc HJ = 5 × 10/8 = 6,25 cm."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[3],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q08","prompt":"Sujet B : D, E, A sont alignés et B, E, F sont alignés ; (DF) ∥ (BA). ED = 7 cm, EA = 4 cm et EF = 8,4 cm. Calcule EB.","expected":"4,8 cm","alternatives":["14,7 cm","2,4 cm","10,5 cm"],"explanation":"ED/EA = EF/EB : 7/4 = 8,4/EB ; EB = 4 × 8,4/7 = 4,8 cm.","feedback":["La réponse « 14,7 cm » est incorrecte : 14,7 inverse les bons facteurs du produit en croix. ED/EA = EF/EB : 7/4 = 8,4/EB ; EB = 4 × 8,4/7 = 4,8 cm.","La réponse « 2,4 cm » est incorrecte : 2,4 correspond à une division supplémentaire injustifiée. ED/EA = EF/EB : 7/4 = 8,4/EB ; EB = 4 × 8,4/7 = 4,8 cm.","La réponse « 10,5 cm » est incorrecte : 10,5 cm est l’autre longueur DF du sujet, pas EB. ED/EA = EF/EB : 7/4 = 8,4/EB ; EB = 4 × 8,4/7 = 4,8 cm."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[3],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q09","prompt":"Dans le sujet A, la voile comporte le triangle AMN rectangle en M, avec AM = 6 m et AN = 7,5 m. Quelle est la longueur MN ?","expected":"4,5 m","alternatives":["13,5 m","1,5 m","√92,25 m"],"explanation":"Comme AN est l’hypoténuse, MN = √(7,5² − 6²) = √20,25 = 4,5 m.","feedback":["La réponse « 13,5 m » est incorrecte : Additionner les longueurs ne donne pas la longueur cherchée. Comme AN est l’hypoténuse, MN = √(7,5² − 6²) = √20,25 = 4,5 m.","La réponse « 1,5 m » est incorrecte : Soustraire 7,5 − 6 ne remplace pas les carrés. Comme AN est l’hypoténuse, MN = √(7,5² − 6²) = √20,25 = 4,5 m.","La réponse « √92,25 m » est incorrecte : Il faut soustraire les carrés, pas les additionner. Comme AN est l’hypoténuse, MN = √(7,5² − 6²) = √20,25 = 4,5 m."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[4],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"},{"questionId":"MT22-Q10","prompt":"Dans le sujet A, ABC est rectangle en B, avec AB = 9 m et BC = 6,75 m. Quelle est l’aire de la voile triangulaire ?","expected":"30,375 m²","alternatives":["60,75 m²","15,75 m²","30,375 m"],"explanation":"Aire = AB × BC/2 = 9 × 6,75/2 = 30,375 m². L’unité est le mètre carré.","feedback":["La réponse « 60,75 m² » est incorrecte : Tu as oublié de diviser le produit par deux. Aire = AB × BC/2 = 9 × 6,75/2 = 30,375 m². L’unité est le mètre carré.","La réponse « 15,75 m² » est incorrecte : Le résultat ne correspond pas à 9 × 6,75/2. Aire = AB × BC/2 = 9 × 6,75/2 = 30,375 m². L’unité est le mètre carré.","La réponse « 30,375 m » est incorrecte : Une aire s’exprime en m² et non en mètres. Aire = AB × BC/2 = 9 × 6,75/2 = 30,375 m². L’unité est le mètre carré."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[4],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS22"}],"MT23":[{"questionId":"MT23-Q01","prompt":"Un élève calcule 5/6 − 11/4 × 4/9 en soustrayant 5/6 − 11/4 en premier. Quelle erreur a-t-il commise ?","expected":"Il n’a pas effectué la multiplication avant la soustraction.","alternatives":["Il fallait additionner toutes les fractions.","Le résultat ne peut jamais être négatif.","Il fallait multiplier les trois fractions."],"explanation":"La multiplication est prioritaire sur la soustraction en l’absence de parenthèses : 11/4 × 4/9 se calcule d’abord.","feedback":["La réponse « Il fallait additionner toutes les fractions. » est incorrecte : L’expression comporte une soustraction, pas une addition générale. La multiplication est prioritaire sur la soustraction en l’absence de parenthèses : 11/4 × 4/9 se calcule d’abord.","La réponse « Le résultat ne peut jamais être négatif. » est incorrecte : Une différence de fractions peut parfaitement être négative. La multiplication est prioritaire sur la soustraction en l’absence de parenthèses : 11/4 × 4/9 se calcule d’abord.","La réponse « Il fallait multiplier les trois fractions. » est incorrecte : Le signe entre 5/6 et 11/4 est « − », pas « × ». La multiplication est prioritaire sur la soustraction en l’absence de parenthèses : 11/4 × 4/9 se calcule d’abord."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q02","prompt":"Un élève écrit 5x − (2x + 9) = 5x − 2x + 9. Quelle est l’erreur à corriger ?","expected":"Le +9 doit devenir −9.","alternatives":["Il faut écrire 5x + 2x + 9.","Il faut supprimer 5x.","Il faut remplacer 9 par 9x."],"explanation":"Le signe moins devant la parenthèse s’applique aux deux termes : 5x − 2x − 9 = 3x − 9.","feedback":["La réponse « Il faut écrire 5x + 2x + 9. » est incorrecte : On doit soustraire 2x et 9, pas ajouter les deux. Le signe moins devant la parenthèse s’applique aux deux termes : 5x − 2x − 9 = 3x − 9.","La réponse « Il faut supprimer 5x. » est incorrecte : Le terme 5x est présent dès le départ et reste dans le calcul. Le signe moins devant la parenthèse s’applique aux deux termes : 5x − 2x − 9 = 3x − 9.","La réponse « Il faut remplacer 9 par 9x. » est incorrecte : Le nombre 9 reste constant : il ne devient pas un terme en x. Le signe moins devant la parenthèse s’applique aux deux termes : 5x − 2x − 9 = 3x − 9."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q03","prompt":"Dans (3x + 2)(4x + 5), un élève écrit 12x² + 15x + 10. Quel produit a-t-il oublié ?","expected":"2 × 4x = 8x","alternatives":["3x × 4x = 12x²","2 × 5 = 10","3x × 5 = 15x"],"explanation":"Un double développement comporte quatre produits. Ici il manque 2 × 4x = 8x ; le résultat devient 12x² + 23x + 10.","feedback":["La réponse « 3x × 4x = 12x² » est incorrecte : Le terme 12x² est déjà présent : ce produit a été fait. Un double développement comporte quatre produits. Ici il manque 2 × 4x = 8x ; le résultat devient 12x² + 23x + 10.","La réponse « 2 × 5 = 10 » est incorrecte : Le terme 10 est déjà présent : ce produit a été fait. Un double développement comporte quatre produits. Ici il manque 2 × 4x = 8x ; le résultat devient 12x² + 23x + 10.","La réponse « 3x × 5 = 15x » est incorrecte : Le terme 15x est déjà écrit : ce n’est pas le produit manquant. Un double développement comporte quatre produits. Ici il manque 2 × 4x = 8x ; le résultat devient 12x² + 23x + 10."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q04","prompt":"Pour (x − 4)(x − 3), un élève écrit x² − 7x − 12. Quelle correction faut-il apporter ?","expected":"Remplacer −12 par +12.","alternatives":["Remplacer −7x par +7x.","Remplacer x² par 2x.","Supprimer le terme constant."],"explanation":"Le produit (−4) × (−3) = +12. Ainsi (x − 4)(x − 3) = x² − 7x + 12.","feedback":["La réponse « Remplacer −7x par +7x. » est incorrecte : Les produits croisés −3x et −4x ont bien une somme négative. Le produit (−4) × (−3) = +12. Ainsi (x − 4)(x − 3) = x² − 7x + 12.","La réponse « Remplacer x² par 2x. » est incorrecte : x × x donne x², pas 2x. Le produit (−4) × (−3) = +12. Ainsi (x − 4)(x − 3) = x² − 7x + 12.","La réponse « Supprimer le terme constant. » est incorrecte : Il faut conserver le produit constant des deux nombres. Le produit (−4) × (−3) = +12. Ainsi (x − 4)(x − 3) = x² − 7x + 12."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q05","prompt":"Dans le programme A, un élève écrit 4x − 2 − 3x + 8 au lieu de 4(x − 2) − 3x + 8. Que manque-t-il ?","expected":"La multiplication de −2 par 4, qui donne −8.","alternatives":["La multiplication de 3x par 4.","Le remplacement de x par 2.","Le changement de +8 en −8."],"explanation":"Distribuer 4 dans 4(x − 2) donne 4x − 8. Le nombre −2 doit aussi être multiplié par 4.","feedback":["La réponse « La multiplication de 3x par 4. » est incorrecte : Le terme −3x est soustrait après la multiplication et ne doit pas être multiplié par 4. Distribuer 4 dans 4(x − 2) donne 4x − 8. Le nombre −2 doit aussi être multiplié par 4.","La réponse « Le remplacement de x par 2. » est incorrecte : Le nombre de départ reste la variable x : on ne la remplace pas arbitrairement par 2. Distribuer 4 dans 4(x − 2) donne 4x − 8. Le nombre −2 doit aussi être multiplié par 4.","La réponse « Le changement de +8 en −8. » est incorrecte : Le +8 final est correct et compense le −8 de la distributivité. Distribuer 4 dans 4(x − 2) donne 4x − 8. Le nombre −2 doit aussi être multiplié par 4."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[2],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q06","prompt":"Le programme B se simplifie en 3x − 12 − 2x + 12. Pourquoi peut-on affirmer que son résultat vaut toujours x ?","expected":"Les constantes s’annulent et 3x − 2x = x.","alternatives":["C’est vrai seulement lorsque x = 9.","On peut supprimer tous les termes en x.","On doit calculer une moyenne de x et 12."],"explanation":"Les termes −12 et +12 s’annulent pour toute valeur de x. Il reste 3x − 2x = x.","feedback":["La réponse « C’est vrai seulement lorsque x = 9. » est incorrecte : Le calcul littéral permet une preuve valable pour toutes les valeurs de x, pas seulement 9. Les termes −12 et +12 s’annulent pour toute valeur de x. Il reste 3x − 2x = x.","La réponse « On peut supprimer tous les termes en x. » est incorrecte : Il reste un terme en x après la réduction : on ne peut pas tout supprimer. Les termes −12 et +12 s’annulent pour toute valeur de x. Il reste 3x − 2x = x.","La réponse « On doit calculer une moyenne de x et 12. » est incorrecte : Aucune moyenne n’intervient dans cette expression. Les termes −12 et +12 s’annulent pour toute valeur de x. Il reste 3x − 2x = x."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[2],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q07","prompt":"Dans le sujet A, un élève écrit GH/HI = HJ/HF alors que GF et JI sont parallèles. Quel est le problème ?","expected":"Le rapport correspondant doit être HF/HJ, pas HJ/HF.","alternatives":["Il faut écrire GH + HI au lieu d’un rapport.","Un angle droit est nécessaire pour écrire Thalès.","Le parallélisme donné empêche d’utiliser Thalès."],"explanation":"Les trois rapports doivent avoir le même sens : GH/HI = HF/HJ = GF/JI, ou bien tous inversés.","feedback":["La réponse « Il faut écrire GH + HI au lieu d’un rapport. » est incorrecte : Thalès repose sur des rapports de longueurs, pas sur la somme GH + HI. Les trois rapports doivent avoir le même sens : GH/HI = HF/HJ = GF/JI, ou bien tous inversés.","La réponse « Un angle droit est nécessaire pour écrire Thalès. » est incorrecte : Un angle droit n’est pas requis pour appliquer Thalès. Les trois rapports doivent avoir le même sens : GH/HI = HF/HJ = GF/JI, ou bien tous inversés.","La réponse « Le parallélisme donné empêche d’utiliser Thalès. » est incorrecte : Au contraire, le parallélisme est une des conditions qui autorise Thalès. Les trois rapports doivent avoir le même sens : GH/HI = HF/HJ = GF/JI, ou bien tous inversés."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[3],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q08","prompt":"Dans le sujet A, un élève fait MN = 7,5 − 6 = 1,5 m dans le triangle AMN rectangle en M. Pourquoi est-ce faux ?","expected":"Pythagore impose MN² = 7,5² − 6², puis la racine carrée.","alternatives":["Il fallait additionner directement 7,5 + 6.","Il fallait utiliser une aire avant toute longueur.","Il fallait prendre 6 comme hypoténuse."],"explanation":"La différence simple des longueurs ne convient pas : √(7,5² − 6²) = 4,5 m.","feedback":["La réponse « Il fallait additionner directement 7,5 + 6. » est incorrecte : Additionner directement les côtés ne produit pas le troisième côté du triangle rectangle. La différence simple des longueurs ne convient pas : √(7,5² − 6²) = 4,5 m.","La réponse « Il fallait utiliser une aire avant toute longueur. » est incorrecte : Pythagore suffit pour trouver MN ; l’aire intervient seulement ensuite. La différence simple des longueurs ne convient pas : √(7,5² − 6²) = 4,5 m.","La réponse « Il fallait prendre 6 comme hypoténuse. » est incorrecte : L’hypoténuse est le côté le plus long, ici 7,5 m. La différence simple des longueurs ne convient pas : √(7,5² − 6²) = 4,5 m."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[4],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q09","prompt":"Pour une voile triangulaire, un élève obtient 30,375 et conclut « 30,375 m ». Pourquoi cette réponse est-elle incomplète ?","expected":"Une aire doit être exprimée en m², pas en m.","alternatives":["Il faut toujours écrire des km².","Le nombre 30,375 doit être remplacé par 30.","Une aire ne porte jamais d’unité."],"explanation":"Une surface est le produit de deux longueurs, donc son unité est une unité carrée : 30,375 m².","feedback":["La réponse « Il faut toujours écrire des km². » est incorrecte : Le mètre carré est adapté aux dimensions de la voile, pas le kilomètre carré. Une surface est le produit de deux longueurs, donc son unité est une unité carrée : 30,375 m².","La réponse « Le nombre 30,375 doit être remplacé par 30. » est incorrecte : On ne modifie pas le résultat numérique exact en le remplaçant arbitrairement par 30. Une surface est le produit de deux longueurs, donc son unité est une unité carrée : 30,375 m².","La réponse « Une aire ne porte jamais d’unité. » est incorrecte : Une aire possède nécessairement une unité adaptée, telle que m². Une surface est le produit de deux longueurs, donc son unité est une unité carrée : 30,375 m²."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[4],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"},{"questionId":"MT23-Q10","prompt":"Le corrigé officiel comporte deux sujets A et B aux valeurs différentes. Quel réflexe évite d’apprendre un mauvais résultat ?","expected":"Identifier son sujet puis contrôler les nombres de son propre énoncé.","alternatives":["Mélanger une longueur du sujet A avec une autre du sujet B.","Apprendre uniquement la réponse finale sans démarche.","Supposer que tous les résultats sont identiques dans les deux sujets."],"explanation":"Les méthodes sont similaires, mais les données et résultats diffèrent : il faut lire le sujet correspondant à sa copie et refaire chaque calcul.","feedback":["La réponse « Mélanger une longueur du sujet A avec une autre du sujet B. » est incorrecte : Les données de deux sujets différents ne sont pas interchangeables. Les méthodes sont similaires, mais les données et résultats diffèrent : il faut lire le sujet correspondant à sa copie et refaire chaque calcul.","La réponse « Apprendre uniquement la réponse finale sans démarche. » est incorrecte : La démarche est essentielle pour comprendre et vérifier un résultat. Les méthodes sont similaires, mais les données et résultats diffèrent : il faut lire le sujet correspondant à sa copie et refaire chaque calcul.","La réponse « Supposer que tous les résultats sont identiques dans les deux sujets. » est incorrecte : Les exercices peuvent être analogues, mais leurs nombres et leurs réponses changent. Les méthodes sont similaires, mais les données et résultats diffèrent : il faut lire le sujet correspondant à sa copie et refaire chaque calcul."],"docId":"ENT-2026correctiondeeval1hDvpetThalespd","pages":[1],"title":"2026 correction de eval 1h Dvp et Thales.pdf","lessonId":"MBIS23"}]};
